/* PsychLogic — Foundational Mock 5 (Psychological Testing & Assessment) question bank.
   Each item: { id, question, options[4], correctAnswer(0-3), subject, explanation, examWatch (PsychLogic Insight) } */
window.MOCK_QUESTIONS = [{"id": 1, "question": "Raven’s Standard Progressive Matrices consists of 60 items arranged in how many sets?", "options": ["3", "5", "6", "10"], "correctAnswer": 1, "subject": "Intelligence & ability tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The SPM (J. C. Raven, 1938) has 60 items in five sets, A to E, of 12 items each, getting harder within and across sets.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>3 sets (A, Ab, B) is the Coloured Progressive Matrices for children and older adults.</li><li>6 and 10 are wrong.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>RML 2022 asked about Raven’s SPM and Raven’s colleagues.</li><li>The Advanced Progressive Matrices (APM) is for high-ability adults.</li><li>Raven’s is seen as a measure of Spearman’s g (‘eductive’ ability) and of fluid intelligence.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — RML 2022. We recommend you keep this area ready."}, {"id": 2, "question": "The Mini-Mental State Examination (Folstein, 1975) includes all of the following areas, EXCEPT:", "options": ["Abstraction (proverb interpretation)", "Attention and calculation", "Orientation", "Registration"], "correctAnswer": 0, "subject": "Interviews, MSE & rating scales", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The 30-point MMSE covers orientation, registration, attention and calculation, recall, language and copying a design. Abstract reasoning is not tested — one reason it misses early frontal and executive problems.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Orientation (10 points), registration (3) and attention/calculation (5) are core MMSE parts.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>JEMAS 2024 asked what the MMSE helps assess.</li><li>The MoCA (Nasreddine, 2005) adds executive, abstraction and visuospatial items and is more sensitive to mild impairment.</li><li>Scores below about 24 suggest cognitive impairment, but education affects scores.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — IHBAS 2025, JEMAS 2024. We recommend you keep this area ready."}, {"id": 3, "question": "In Gardner Lindzey’s (1959) classification of projective techniques, the Rotter Incomplete Sentences Blank is an example of a(n):", "options": ["Expressive technique", "Association technique", "Construction technique", "Completion technique"], "correctAnswer": 3, "subject": "Projective tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Lindzey grouped projectives by the kind of response: association (Rorschach, word association), construction (TAT — build a story), completion (sentence completion, Rosenzweig P-F), choice/ordering (Szondi) and expression (drawing, play, psychodrama).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Association – respond with the first thing that comes to mind (Rorschach).</li><li>Construction – create a story or product (TAT, CAT).</li><li>Expression – drawings, play, role-play.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>M.Phil Entrance 2021 asked which type of projective technique the Rorschach is (association).</li><li>Rotter’s ISB (1950) has 40 sentence stems.</li><li>JEMAS 2022/2024 and JEPAS 2020 asked where projective tests originated (Freud’s idea of unconscious motives).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>12 of them</b> (recent examples: IMHANS 2025, IHBAS 2025, GBU 2025, RML 2024). We recommend you focus on this area."}, {"id": 4, "question": "The Scale for the Assessment of Negative Symptoms (SANS) and the Scale for the Assessment of Positive Symptoms (SAPS) were developed by:", "options": ["Timothy Crow", "John Overall", "Nancy Andreasen", "Stanley Kay"], "correctAnswer": 2, "subject": "Clinical assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Nancy Andreasen developed the SANS (early 1980s) and SAPS (1984) to rate negative and positive symptoms of schizophrenia in detail.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Crow proposed the Type I / Type II schizophrenia distinction (1980).</li><li>Kay co-developed the PANSS.</li><li>Overall co-developed the BPRS.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The five SANS areas: affective flattening, alogia, avolition–apathy, anhedonia–asociality, attention.</li><li>Crow’s Type I (positive symptoms, good drug response) vs Type II (negative symptoms, structural brain changes).</li><li>IHBAS 2025, JEMAS 2024 and JANAS asked about positive or negative symptoms.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — IHBAS 2025, J&amp;K 2023. We recommend you keep this area ready."}, {"id": 5, "question": "The original Bender Visual Motor Gestalt Test (1938) asks the person to copy how many geometric designs?", "options": ["9", "10", "12", "16"], "correctAnswer": 0, "subject": "Neuropsychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Lauretta Bender’s test has 9 designs (card A plus cards 1–8), adapted from Max Wertheimer’s Gestalt perception figures. Copying errors such as rotation or distortion suggest visuo-motor or organic problems.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>16 is the Bender–Gestalt II (2003).</li><li>10 is the number of Rorschach cards, a common confusion.</li><li>12 is wrong.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Scoring systems: Pascal &amp; Suttell (adults) and Koppitz (children).</li><li>The Bender test is part of the PGI Battery of Brain Dysfunction.</li><li>It is used as a quick screen for brain dysfunction and visuo-motor maturity.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — RINPAS 2024, M.Phil Entrance 2021. We recommend you keep this area ready."}, {"id": 6, "question": "A test has a standard deviation of 15 and a reliability coefficient of 0.91. What is its standard error of measurement (SEM)?", "options": ["1.35", "4.5", "13.5", "13.65"], "correctAnswer": 1, "subject": "Reliability, validity & norms", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> SEM = SD × √(1 – r) = 15 × √(0.09) = 15 × 0.3 = 4.5. So a person’s true score will lie within about ±4.5 points of the obtained score about 68% of the time.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>1.35 = 15 × 0.09 (forgot the square root).</li><li>13.5 = 15 × 0.9 (used √r instead of √(1 – r)).</li><li>13.65 = 15 × 0.91.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>If reliability = 1.00, SEM = 0 (asked in IMHANS 2021).</li><li>Confidence band: obtained score ± 1.96 SEM gives the 95% range.</li><li>Higher reliability → smaller SEM → more precise scores.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — IMHANS 2021. We recommend you keep this area ready."}, {"id": 7, "question": "Read the Assertion (A) and Reason (R) and choose the correct option: Assertion (A): Developmental screening tests such as the Denver II should not be used to diagnose developmental delay. Reason (R): The Denver Developmental Screening Test was developed by William Frankenburg and Josiah Dodds.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is NOT the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "correctAnswer": 1, "subject": "Developmental & child assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Both are true. Screeners like the Denver II are short and only flag children who need detailed assessment, so they should not be used to diagnose. R is a correct historical fact, but who developed the test does not explain why screening tests cannot diagnose, so R is not the explanation.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>A is wrong because R does not explain A.</li><li>C and D are wrong because both statements are true.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Screening tests aim for high sensitivity (few missed cases), even at the cost of false positives.</li><li>GMCH 2023 asked how sensitivity is defined.</li><li>Primary prevention vs early identification is a related public-health concept.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — GMCH 2023. We recommend you keep this area ready."}, {"id": 8, "question": "During a Mental Status Examination, a patient calmly explains that his neighbour controls his movements through radio waves. The clinician should record this mainly under:", "options": ["Orientation", "Form (process) of thought", "Thought content", "Perception"], "correctAnswer": 2, "subject": "Interviews, MSE & rating scales", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> What a person thinks about — delusions, obsessions, suicidal ideas — is recorded under thought content. This belief is a delusion of control (a passivity phenomenon).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Form of thought – HOW ideas are linked (e.g. loosening of associations, tangentiality).</li><li>Perception – hallucinations and illusions.</li><li>Orientation – awareness of time, place and person.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>MSE headings: appearance and behaviour, speech, mood and affect, thought (form and content), perception, cognition, insight, judgement.</li><li>IHBAS 2024 asked about persecutory delusional beliefs; RML 2022 asked about grades of insight.</li><li>Passivity phenomena (‘made’ acts) are Schneiderian first-rank symptoms.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — IMHANS 2025. We recommend you keep this area ready."}, {"id": 9, "question": "On a Wechsler scale (mean 100, SD 15), a person scores an IQ of 115. Approximately what percentile does this correspond to?", "options": ["50th", "68th", "84th", "98th"], "correctAnswer": 2, "subject": "Reliability, validity & norms", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> IQ 115 is exactly +1 SD (z = +1). In a normal curve, about 50% of scores lie below the mean and about 34% lie between the mean and +1 SD. So about 84% score below 115 — the 84th percentile.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>50th = IQ 100 (the mean).</li><li>68% is the share between –1 and +1 SD, not a percentile.</li><li>98th ≈ IQ 130 (+2 SD).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>About 16% of scores lie above z = +1 — asked in JEMAS 2022, JEMAS 2024, JANAS and JEPAS 2020.</li><li>68–95–99.7 rule: ±1, ±2, ±3 SD.</li><li>Percentiles are ordinal — equal percentile gaps are not equal score gaps (NFSU 2023 asked about percentiles).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>8 of them</b> (recent examples: RINPAS 2024, JEMAS 2024, NFSU 2023, RML 2022). We recommend you focus on this area."}, {"id": 10, "question": "On a personality questionnaire, Rakesh agrees with almost every statement, even contradictory ones such as ‘I love big parties’ and ‘I avoid parties whenever I can’. This response style is called:", "options": ["Central tendency", "Social desirability", "Halo effect", "Acquiescence"], "correctAnswer": 3, "subject": "Objective personality tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Acquiescence is the tendency to say ‘yes’ or ‘agree’ regardless of the content. Agreeing with opposite statements is the clue.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Social desirability – choosing answers that make one look good.</li><li>Central tendency – choosing the middle option.</li><li>Halo effect – one good quality colours all ratings of a person.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>RML 2024 asked for the name of this response bias.</li><li>Balanced scales with reverse-keyed items help detect acquiescence.</li><li>Response sets vs response styles: Cronbach and Jackson &amp; Messick debated how much they distort scores.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — RML 2024, IMHANS 2021. We recommend you keep this area ready."}, {"id": 11, "question": "The Binet–Simon scale of 1905 was originally developed to:", "options": ["Identify Paris schoolchildren who needed special educational help", "Diagnose psychiatric patients in asylums", "Measure sensory acuity and reaction time", "Select army recruits for officer training"], "correctAnswer": 0, "subject": "History & foundations", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The French government asked Alfred Binet and Théodore Simon to find children who could not benefit from ordinary schooling. Their 1905 scale had 30 items of increasing difficulty; the 1908 revision introduced ‘mental age’.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Army selection was the purpose of Army Alpha and Beta (1917).</li><li>Sensory and reaction-time tests were Galton’s and Cattell’s approach.</li><li>It was an educational, not psychiatric, tool.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>JEMAS 2022, JANAS and GBU 2025 asked who developed the first intelligence test (Binet and Simon).</li><li>Henry Goddard translated the Binet scale into English (1908).</li><li>Binet saw intelligence as judgement, reasoning and comprehension — not simple sensation.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>11 of them</b> (recent examples: GBU 2025, NFSU 2023, GMCH 2023, JEMAS 2022). We recommend you focus on this area."}, {"id": 12, "question": "While building a fear hierarchy, a therapist asks the client to rate how anxious each situation makes her on a scale from 0 to 100. This rating is called:", "options": ["Global Assessment of Functioning", "Visual Analogue Pain Scale", "Beck Anxiety Inventory", "Subjective Units of Distress (SUDS)"], "correctAnswer": 3, "subject": "Behavioural assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Joseph Wolpe introduced SUDS: a 0–100 self-rating of distress. It is used to order items in systematic desensitization and to track anxiety during exposure.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>VAS for pain measures pain, not a hierarchy.</li><li>GAF rates overall functioning (dropped in DSM-5).</li><li>BAI is a 21-item questionnaire, not a quick moment-to-moment rating.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Systematic desensitization is based on reciprocal inhibition (IHBAS 2025).</li><li>JANAS asked what desensitization is mainly used for (phobias).</li><li>During exposure, a fall in SUDS shows habituation.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>8 of them</b> (recent examples: IHBAS 2025, NFSU 2023, RML 2022, JEMAS 2022). We recommend you focus on this area."}, {"id": 13, "question": "The Wechsler Preschool and Primary Scale of Intelligence, fourth edition (WPPSI-IV), is meant for children aged about:", "options": ["21⁄2 to 71⁄2 years", "6 to 16 years", "16 to 90 years", "1 to 42 months"], "correctAnswer": 0, "subject": "Developmental & child assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The WPPSI-IV covers 2 years 6 months to 7 years 7 months. WISC-V covers 6–16 years; WAIS covers 16–90 years.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>6–16 is WISC-V.</li><li>16–90 is WAIS-IV.</li><li>1–42 months is the Bayley Scales.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Wechsler family: WPPSI (preschool), WISC (children), WAIS (adults), WASI (abbreviated scale).</li><li>Overlapping ages let clinicians choose the scale best suited to the child’s ability.</li><li>Gurugram asked what the Wechsler tests contain (verbal and performance scales).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>10 of them</b> (recent examples: IMHANS 2025, GBU 2025, RINPAS 2024, NFSU 2023). We recommend you focus on this area."}, {"id": 14, "question": "A client asks for a copy of her MMPI-2 answers and scores. Separately, a non-psychologist colleague asks to borrow the MMPI-2 booklet and scoring keys. Under the APA Ethics Code (2017), the psychologist should:", "options": ["Give the booklet to the colleague but not the data to the client", "Give both the data and the booklet, since the client consented", "Provide the client’s test data, unless release would cause substantial harm, but keep the test materials secure", "Refuse both requests, since all test information is confidential"], "correctAnswer": 2, "subject": "Ethics & legal aspects of testing", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> APA Standard 9.04 allows release of test data (the client’s responses and scores) to the client or others named in a release, unless this would cause substantial harm or misuse. Standard 9.11 requires psychologists to protect test materials (manuals, items, protocols) so the tests stay valid.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Refusing the client’s own data is not required by the Code.</li><li>Test materials must never be handed out freely.</li><li>This reverses the two rules.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>APA Standard 9.02: use tests whose validity and reliability are established for the population tested.</li><li>APA Standard 9.07: do not promote use of tests by unqualified persons.</li><li>J&amp;K 2023 and JANAS asked about the ethical principles of psychologists.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>4 papers</b> — IMHANS 2025, J&amp;K 2023, JEPAS 2020, JANAS. We recommend you keep this area ready."}, {"id": 15, "question": "Read the Assertion (A) and Reason (R) and choose the correct option: Assertion (A): A test cannot be reliable unless it is also valid. Reason (R): Reliability is necessary but not sufficient for validity.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is NOT the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "correctAnswer": 3, "subject": "Reliability, validity & norms", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> A is false: a test can be highly reliable (consistent) and still not valid — for example, a very consistent scale that measures the wrong thing. R is true: a test must be reliable to be valid, but reliability alone does not guarantee validity. The Assertion reverses the real relationship.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>A, B and C all treat the Assertion as true, which it is not.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Validity coefficient cannot exceed the square root of reliability.</li><li>IMHANS 2025 asked about a test with high alpha that fails to predict an outcome; IMHANS 2021 asked about a test that is consistent but does not measure what it claims.</li><li>Reliability = consistency; validity = accuracy (‘measuring what it claims to measure’).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — IMHANS 2025, IMHANS 2021. We recommend you keep this area ready."}, {"id": 16, "question": "Compared with the MMPI, the Millon Clinical Multiaxial Inventory (MCMI) is designed especially to assess:", "options": ["Normal personality traits in the general population", "Personality disorders and clinical syndromes, using base-rate scores tied to Millon’s theory", "Vocational interests", "General intelligence and aptitude"], "correctAnswer": 1, "subject": "Objective personality tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The MCMI (Theodore Millon) is shorter than the MMPI and focuses on personality disorders and related clinical syndromes. It uses base-rate (BR) scores, which reflect how common each disorder is, instead of ordinary T-scores. The MCMI-IV (2015) has 195 true–false items.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Normal traits are measured by the NEO, 16PF or CPI.</li><li>Intelligence and aptitude need ability tests.</li><li>Interests need inventories like Holland’s SDS.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>JANAS asked how many items the MCMI-III has (175) and which scales count as ‘severe personality pathology’.</li><li>The MCMI was built with a rational–theoretical plus empirical approach.</li><li>The CPI (Gough) is often called the ‘normal person’s MMPI’ (M.Phil Entrance 2021 asked the difference).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — GMCH 2023, JANAS. We recommend you keep this area ready."}, {"id": 17, "question": "In classical item analysis, an item with a difficulty index (p) of 0.90 is:", "options": ["A highly discriminating item", "An easy item — 90% of test-takers answered it correctly", "An item with a reliability of 0.90", "A hard item — 90% of test-takers got it wrong"], "correctAnswer": 1, "subject": "Reliability, validity & norms", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The difficulty index p is simply the proportion of people who answer an item correctly. A higher p means an EASIER item.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The index is the proportion correct, not wrong.</li><li>Discrimination is a separate index (D).</li><li>Item difficulty is not a reliability coefficient.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>For most ability tests, items of moderate difficulty (p around 0.5) give the most information.</li><li>IMHANS 2021 defined a test item as a single task that cannot be broken down further.</li><li>NFSU 2023 asked about item analysis of speeded tests.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>3 papers</b> — IMHANS 2025, NFSU 2023, IMHANS 2021. We recommend you keep this area ready."}, {"id": 18, "question": "The 1890 paper ‘Mental Tests and Measurements’, which introduced the term ‘mental test’, was written by:", "options": ["Alfred Binet", "Francis Galton", "James McKeen Cattell", "Wilhelm Wundt"], "correctAnswer": 2, "subject": "History & foundations", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> James McKeen Cattell, an American student of Wundt who was also influenced by Galton, coined the term ‘mental test’ in 1890. His tests measured simple sensory and reaction-time abilities.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Galton – set up the Anthropometric Laboratory (London, 1884) and pioneered correlation, but did not coin the term.</li><li>Binet – built the first practical intelligence scale (1905).</li><li>Wundt – founded the first psychology laboratory (Leipzig, 1879).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Clark Wissler (1901) showed that Cattell’s sensory tests did not predict college grades — a turning point towards Binet’s approach.</li><li>Galton is called the father of psychometrics and of differential psychology.</li><li>IMHANS 2021 asked who invented the term ‘mental test’.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — IMHANS 2021, IHBAS Paper-II. We recommend you keep this area ready."}, {"id": 19, "question": "A psychologist observes a 5-year-old boy and rates 15 areas — relating to people, imitation, emotional response, body use, adaptation to change and others — to judge whether he has autism and how severe it is. The scale being used is the:", "options": ["Childhood Autism Rating Scale (CARS)", "Child Behavior Checklist (CBCL)", "Vineland Social Maturity Scale", "Conners Rating Scales"], "correctAnswer": 0, "subject": "Clinical assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The CARS (Schopler and colleagues, 1980) has 15 items, each rated 1–4 from observation. Totals of 30 or more suggest autism; 37 or more suggests severe autism.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Conners – ADHD symptoms.</li><li>CBCL – broad emotional and behavioural problems.</li><li>VSMS – social maturity and adaptive behaviour.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>ADOS-2 is the gold-standard observational assessment for autism.</li><li>M-CHAT screens toddlers (16–30 months).</li><li>In India, ISAA is used for certification (IHBAS 2024).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — IHBAS 2024. We recommend you keep this area ready."}, {"id": 20, "question": "Assessing a client across Behaviour, Affect, Sensation, Imagery, Cognition, Interpersonal relationships and Drugs/biology is known as:", "options": ["Beck’s cognitive case conceptualisation", "Ellis’s ABC assessment", "Kanfer’s SORKC analysis", "Arnold Lazarus’s multimodal (BASIC ID) assessment"], "correctAnswer": 3, "subject": "Behavioural assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Arnold Lazarus’s multimodal therapy assesses seven modalities summarised as BASIC ID, then chooses techniques for each problem area.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Beck’s conceptualisation focuses on core beliefs and automatic thoughts.</li><li>Ellis’s ABC links Activating event, Beliefs and emotional Consequences.</li><li>SORKC is Kanfer’s behavioural formula.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Lazarus also coined the term ‘behaviour therapy’ in the clinical literature (1958).</li><li>Multimodal therapy is technically eclectic — it borrows techniques without mixing theories.</li><li>Ellis’s ABC–DE model: D stands for disputing (IHBAS 2025 asked this).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 21, "question": "On a new test item, more low scorers than high scorers get the answer right. The item’s discrimination index is:", "options": ["Highly positive — the item works well", "Zero — which is ideal", "Equal to its difficulty index", "Negative — the item should be revised or removed"], "correctAnswer": 3, "subject": "Reliability, validity & norms", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The discrimination index D = (proportion correct in the upper group) – (proportion correct in the lower group). If low scorers do better, D is negative. The item is probably misleading or wrongly keyed.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>D = 0 means the item does not discriminate at all — not ideal.</li><li>A positive D would mean high scorers do better.</li><li>Difficulty and discrimination are different indices.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Upper and lower groups are often the top and bottom 27% (Kelley).</li><li>D of about 0.40 or above is considered very good.</li><li>The item–total correlation (point-biserial) is another discrimination measure.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — NFSU 2023. We recommend you keep this area ready."}, {"id": 22, "question": "A test in which items become progressively harder and the time limit is generous, so that scores show the most difficult level a person can reach, is called a:", "options": ["Speed test", "Typical-performance test", "Power test", "Criterion-referenced test"], "correctAnswer": 2, "subject": "History & foundations", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> A power test measures the level of difficulty a person can handle when time is not the main limit. A speed test uses easy items and a strict time limit, so the score depends on how many are finished.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Speed test – easy items, strict time limit.</li><li>Criterion-referenced – compares performance with a fixed standard, not about time.</li><li>Typical performance – what a person usually does (e.g. personality), not their best.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Split-half reliability gives falsely high values for pure speed tests (NFSU 2023 asked about item analysis of speeded tests).</li><li>Most real tests are a mix of speed and power.</li><li>Achievement and aptitude tests are ‘maximal performance’ tests.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — NFSU 2023, RML 2022. We recommend you keep this area ready."}, {"id": 23, "question": "Read the Assertion (A) and Reason (R) and choose the correct option: Assertion (A): Word association tests can reveal a person’s emotional complexes. Reason (R): Jung found that long reaction times, repeated words and unusual responses tend to occur to emotionally charged stimulus words.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is NOT the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "correctAnswer": 0, "subject": "Projective tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Both are true, and R explains A. In his association studies (1904–1910), Carl Jung used ‘complex indicators’ — delayed responses, failures, repeating the stimulus word — to locate emotionally loaded areas (complexes).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>R is the very mechanism that makes A true, so B is wrong.</li><li>C and D are wrong because both statements are true.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Galton first experimented with word association (1879).</li><li>The Kent–Rosanoff list (1910) has 100 common words with norms.</li><li>In Lindzey’s scheme, word association is an association technique.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 24, "question": "All of the following are structured or semi-structured diagnostic interviews, EXCEPT:", "options": ["K-SADS", "Thematic Apperception Test", "SCID-5", "MINI"], "correctAnswer": 1, "subject": "Clinical assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> SCID-5 (for DSM-5 diagnoses), the MINI (a short structured interview) and the K-SADS (for children and adolescents) are diagnostic interviews. The TAT is a projective personality test.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>SCID-5, MINI and K-SADS are all genuine diagnostic interviews.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Structured interviews improve the reliability of diagnosis.</li><li>The Present State Examination and SCAN are the WHO-linked interviews.</li><li>GBU 2025 asked which testing method uses ambiguous stimuli (projective tests).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>3 papers</b> — IMHANS 2025, IHBAS 2025, JEPAS 2020. We recommend you keep this area ready."}, {"id": 25, "question": "On the Rosenzweig Picture-Frustration Study, a respondent answers a frustrating cartoon scene with: ‘It’s my own fault — I should have been more careful.’ In Rosenzweig’s scoring, this reaction is:", "options": ["Need-persistent", "Extrapunitive", "Intropunitive", "Impunitive"], "correctAnswer": 2, "subject": "Projective tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Rosenzweig scored the direction of aggression: extrapunitive (blaming others), intropunitive (blaming oneself) and impunitive (blaming no one — glossing over the situation). Blaming oneself is intropunitive.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Extrapunitive – ‘It’s your fault!’</li><li>Impunitive – ‘It doesn’t matter, it couldn’t be helped.’</li><li>Need-persistence is a reaction TYPE (focus on solving the problem), not a direction.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The P-F Study (Saul Rosenzweig, 1945) has 24 cartoon frustration scenes.</li><li>Reaction types: obstacle-dominance, ego-defence, need-persistence.</li><li>In Lindzey’s scheme the P-F Study is a completion technique.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 26, "question": "Match the neuropsychological test (List I) with the main function it assesses (List II): Codes:<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>List I</th><th>List II</th></tr></thead><tbody><tr><td>1. Stroop Colour–Word Test</td><td>a. Visual memory</td></tr><tr><td>2. Rey Auditory Verbal Learning Test</td><td>b. Planning and problem solving</td></tr><tr><td>3. Benton Visual Retention Test</td><td>c. Response inhibition (selective attention)</td></tr><tr><td>4. Tower of London</td><td>d. Verbal learning and memory</td></tr></tbody></table></div>", "options": ["1-d, 2-c, 3-a, 4-b", "1-c, 2-a, 3-d, 4-b", "1-c, 2-d, 3-b, 4-a", "1-c, 2-d, 3-a, 4-b"], "correctAnswer": 3, "subject": "Neuropsychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Stroop → inhibiting the automatic reading response; Rey AVLT → learning a 15-word list over trials; Benton VRT → remembering and drawing designs; Tower of London (Shallice, 1982) → planning moves ahead.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The other codes swap the two memory tests or the two executive tests.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Stroop is one of the most repeated items: JEMAS 2022, JEMAS 2024, JANAS, JEPAS 2020, RML 2024, IHBAS 2024 and GBU 2025.</li><li>IMHANS 2025 listed the BVRT and Rey–Osterrieth Complex Figure as options.</li><li>The Tower of Hanoi is the older, harder cousin of the Tower of London.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>10 of them</b> (recent examples: IMHANS 2025, GBU 2025, RML 2024, JEMAS 2024). We recommend you focus on this area."}, {"id": 27, "question": "Which Rorschach cards are fully chromatic (multicoloured)?", "options": ["VIII, IX and X", "II, III and VIII", "II and III", "I, IV, V, VI and VII"], "correctAnswer": 0, "subject": "Projective tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Of the 10 Rorschach cards, five are achromatic (I, IV, V, VI, VII), two are black-and-red (II, III) and three are fully coloured (VIII, IX, X).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>II and III are black with red, not fully chromatic.</li><li>I, IV, V, VI and VII are the achromatic cards (asked in M.Phil Entrance 2021).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>RML 2022 asked how many Rorschach cards are coloured; GBU 2025 asked what types of cards are included.</li><li>Hermann Rorschach published Psychodiagnostik in 1921.</li><li>Card V is usually the easiest card; its popular response is a bat or butterfly.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>8 of them</b> (recent examples: GBU 2025, RINPAS 2024, IHBAS 2024, GMCH 2023). We recommend you focus on this area."}, {"id": 28, "question": "Match the standard score (List I) with its mean and standard deviation (List II): Codes:<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>List I</th><th>List II</th></tr></thead><tbody><tr><td>1. z-score</td><td>a. Mean 50, SD 10</td></tr><tr><td>2. T-score</td><td>b. Mean 100, SD 15</td></tr><tr><td>3. Wechsler deviation IQ</td><td>c. Mean 0, SD 1</td></tr><tr><td>4. Stanine</td><td>d. Mean 5, SD about 2</td></tr></tbody></table></div>", "options": ["1-a, 2-c, 3-b, 4-d", "1-c, 2-a, 3-b, 4-d", "1-c, 2-b, 3-a, 4-d", "1-c, 2-a, 3-d, 4-b"], "correctAnswer": 1, "subject": "Reliability, validity & norms", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> z: mean 0, SD 1. T: mean 50, SD 10. Deviation IQ: mean 100, SD 15. Stanine (‘standard nine’): 1–9, mean 5, SD about 2.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The other codes swap the T-score and IQ scales — the usual trap.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Sten scores (used in the 16PF): 1–10, mean 5.5, SD 2.</li><li>MMPI profiles use T-scores; T ≥ 65 is usually taken as clinically significant on the MMPI-2.</li><li>J&amp;K 2023 asked ‘Raw scores are to z-scores as...’.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>6 of them</b> (recent examples: JEMAS 2024, J&amp;K 2023, JEMAS 2022, JEPAS 2020). We recommend you focus on this area."}, {"id": 29, "question": "All of the following are performance (non-verbal) tests, EXCEPT:", "options": ["Army Alpha", "Porteus Maze Test", "Seguin Form Board", "Kohs’ Block Design Test"], "correctAnswer": 0, "subject": "History & foundations", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Army Alpha was a written, verbal group test. The other three need no reading or speaking — the person works with mazes, blocks or shapes.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Porteus Maze – tracing mazes to test planning and foresight.</li><li>Kohs’ Blocks – copying designs with coloured cubes.</li><li>Seguin Form Board – fitting shapes into holes as fast as possible.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Porteus developed his maze test for testing ‘planning’ in people with limited language — JEMAS 2024, JANAS and JEPAS 2020 asked what it was based on.</li><li>Performance tests are used with children, people with hearing or language problems, and across cultures.</li><li>Kohs’ Blocks appear in the Bhatia Battery and inspired Wechsler’s Block Design.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>3 papers</b> — JEMAS 2024, JEPAS 2020, JANAS. We recommend you keep this area ready."}, {"id": 30, "question": "The correlation between the odd and even halves of a test is 0.60. Using the Spearman–Brown formula, the estimated reliability of the full test is:", "options": ["0.60", "0.75", "0.80", "1.20"], "correctAnswer": 1, "subject": "Reliability, validity & norms", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Spearman–Brown: r_full = 2r_half / (1 + r_half) = 1.20 / 1.60 = 0.75. The split-half correlation underestimates reliability because each half is only half as long as the full test.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>0.60 is only the half-test correlation.</li><li>1.20 is impossible — reliability cannot exceed 1.</li><li>0.80 is an arithmetic slip.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>RML 2022 asked about the odd–even method of splitting a test.</li><li>Longer tests are more reliable (the general form of Spearman–Brown predicts this).</li><li>Rulon and Flanagan formulas are alternatives to Spearman–Brown.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>3 papers</b> — RML 2022, IMHANS 2021, IHBAS Paper-II. We recommend you keep this area ready."}, {"id": 31, "question": "The Alcohol Use Disorders Identification Test (AUDIT), developed by the WHO, contains how many items?", "options": ["4", "10", "20", "25"], "correctAnswer": 1, "subject": "Clinical assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The AUDIT (WHO, 1989) has 10 items on alcohol intake, dependence symptoms and alcohol-related harm. A score of 8 or more usually suggests hazardous or harmful drinking.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>4 items = the CAGE questionnaire.</li><li>20 and 25 are not AUDIT versions.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>JANAS asked who developed the AUDIT (WHO).</li><li>AUDIT-C is a 3-item short version (consumption items only).</li><li>CAGE: Cut down, Annoyed, Guilty, Eye-opener.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — JANAS. We recommend you keep this area ready."}, {"id": 32, "question": "Match the test (List I) with the theory it is mainly based on (List II): Codes:<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>List I</th><th>List II</th></tr></thead><tbody><tr><td>1. Das–Naglieri Cognitive Assessment System</td><td>a. Cattell–Horn–Carroll (CHC) factors</td></tr><tr><td>2. Kaufman Assessment Battery for Children (original)</td><td>b. Spearman’s g</td></tr><tr><td>3. Stanford–Binet, 5th edition</td><td>c. PASS theory</td></tr><tr><td>4. Raven’s Progressive Matrices</td><td>d. Luria’s sequential vs simultaneous processing</td></tr></tbody></table></div>", "options": ["1-d, 2-c, 3-a, 4-b", "1-c, 2-a, 3-d, 4-b", "1-c, 2-d, 3-b, 4-a", "1-c, 2-d, 3-a, 4-b"], "correctAnswer": 3, "subject": "Intelligence & ability tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> CAS (1997) measures PASS: Planning, Attention, Simultaneous and Successive processing. The K-ABC (1983) was built on Luria’s sequential vs simultaneous processing. The SB5 (2003) uses five CHC factors. Raven’s is a classic measure of g.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The other codes mix up PASS with Luria (PASS itself grew from Luria’s work, which is the trap).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>PASS theory: Das, Naglieri &amp; Kirby (1994).</li><li>UGC NET December 2024 had the PASS model among its high-weightage topics.</li><li>The Cattell–Horn–Carroll model is the basis of most modern IQ tests.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — M.Phil Entrance 2021. We recommend you keep this area ready."}, {"id": 33, "question": "In Rorschach scoring, the determinant ‘M’ stands for:", "options": ["Pure colour", "Inanimate movement", "Human movement", "Animal movement"], "correctAnswer": 2, "subject": "Projective tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> M is scored when the person sees humans (or human-like figures) in action. Rorschach linked M to imagination and inner life (introversive ‘experience type’).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>FM – animal movement.</li><li>m – inanimate movement (e.g. an exploding volcano), often linked to situational stress.</li><li>C – pure colour.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Location codes: W (whole blot), D (common detail), Dd (unusual detail), S (white space).</li><li>Other determinants: F (form), C/CF/FC (colour), Y (shading), T (texture), V (vista).</li><li>IMHANS 2021 asked which category CANNOT be used to classify Rorschach responses.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>8 of them</b> (recent examples: GBU 2025, RINPAS 2024, IHBAS 2024, GMCH 2023). We recommend you focus on this area."}, {"id": 34, "question": "A teacher records: whenever 8-year-old Aarav is given a maths worksheet (A), he throws his book on the floor (B), and he is then sent out of the classroom (C). A functional analysis suggests his behaviour is most likely maintained by:", "options": ["Sensory stimulation", "Teacher attention (positive reinforcement)", "Punishment of the behaviour", "Escape from the task (negative reinforcement)"], "correctAnswer": 3, "subject": "Behavioural assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Being sent out removes the hated worksheet. Removing something unpleasant makes a behaviour more likely — negative reinforcement. So throwing the book ‘works’ as an escape.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Attention would fit if the teacher scolded or comforted him in class, but here the consequence is leaving the task.</li><li>Nothing suggests he enjoys the sensation of throwing.</li><li>Being sent out is not punishing him — it rewards him by ending the task.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Functional analysis is part of behaviour therapy (RINPAS 2024, JANAS, JEPAS 2020).</li><li>Common functions of behaviour: attention, escape, access to tangibles, sensory (automatic).</li><li>Treatment idea: stop letting the behaviour produce escape, and teach an appropriate way to ask for a break.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>4 papers</b> — RINPAS 2024, RML 2022, JEPAS 2020, JANAS. We recommend you keep this area ready."}, {"id": 35, "question": "On a card-sorting task, a patient keeps sorting by colour even after being told ‘wrong’ many times following a change in the sorting rule. This pattern is scored as ______ and most suggests ______.", "options": ["Set-loss errors; occipital lobe damage", "Perseverative errors; cerebellar ataxia", "Perseverative errors; dorsolateral prefrontal dysfunction", "Random errors; hippocampal amnesia"], "correctAnswer": 2, "subject": "Neuropsychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> This is the Wisconsin Card Sorting Test. Sticking to an old rule after feedback says it is wrong is a perseverative error. It shows poor set-shifting (cognitive flexibility), typical of dorsolateral prefrontal dysfunction.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The occipital lobe processes vision, not rule-shifting.</li><li>Hippocampal damage mainly affects new memory, not rule flexibility.</li><li>Cerebellar damage affects coordination, not card-sorting rules.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>M.Phil Entrance 2021 asked which test measures set-shifting.</li><li>IMHANS 2025 asked which test is most sensitive to subtle frontal executive dysfunction (WCST).</li><li>WCST was developed by Grant and Berg (1948).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>3 papers</b> — IMHANS 2025, M.Phil Entrance 2021, JANAS. We recommend you keep this area ready."}, {"id": 36, "question": "A researcher gives the same anxiety scale to 100 students twice, three weeks apart, and correlates the two sets of scores. The main source of error this method detects is:", "options": ["Time sampling (changes in people over time)", "Content sampling (the particular items chosen)", "Heterogeneity of item content", "Inter-scorer differences"], "correctAnswer": 0, "subject": "Reliability, validity & norms", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Test–retest reliability shows how stable scores are over time. Its error comes from time sampling — mood, practice, fatigue or real change between the two sessions.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Content sampling error is detected by split-half or parallel forms.</li><li>Inter-scorer error is detected by comparing two scorers.</li><li>Heterogeneity of content lowers internal consistency (alpha).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Anastasi’s four sources of error: time sampling, content sampling, content heterogeneity, and scorer differences.</li><li>Too short an interval → memory inflates r; too long → real change lowers r.</li><li>M.Phil Entrance 2021 and IMHANS 2021 asked about test–retest reliability.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>4 papers</b> — RINPAS 2024, M.Phil Entrance 2021, IMHANS 2021, IHBAS Paper-II. We recommend you keep this area ready."}, {"id": 37, "question": "A psychologist must document a patient’s functioning in six domains — understanding and communicating, getting around, self-care, getting along with people, life activities and participation in society. The measure recommended in DSM-5 for this is:", "options": ["Vineland Social Maturity Scale", "WHODAS 2.0", "Clinical Global Impression (CGI)", "Global Assessment of Functioning (GAF)"], "correctAnswer": 1, "subject": "Interviews, MSE & rating scales", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> DSM-5 dropped the multi-axial system and the GAF. It recommends the WHO Disability Assessment Schedule 2.0 (36 items, six domains), which is based on the ICF.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>GAF – removed from DSM-5.</li><li>CGI – a single global severity and improvement rating.</li><li>VSMS – measures social maturity in children.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>DSM-5 dropped the axes (JEMAS 2022 and JEPAS 2020 asked what DSM-IV-TR provided; NFSU 2023 asked about Axis I).</li><li>The DSM-5-TR Cultural Formulation Interview has 16 questions (IMHANS 2025).</li><li>WHODAS has 36-item and 12-item versions, self- or interviewer-administered.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>4 papers</b> — NFSU 2023, JEMAS 2022, IMHANS 2021, JEPAS 2020. We recommend you keep this area ready."}, {"id": 38, "question": "A 68-year-old retired teacher complains of forgetfulness, and her daughter says she now struggles to plan meals and pay bills. She scores 29/30 on the MMSE. The most useful next screening test is the:", "options": ["Beck Depression Inventory-II", "Bender Visual Motor Gestalt Test", "Montreal Cognitive Assessment (MoCA)", "Raven’s Coloured Progressive Matrices"], "correctAnswer": 2, "subject": "Clinical assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The MMSE has a ‘ceiling effect’ in educated people and tests executive function poorly. The MoCA (Nasreddine, 2005) includes trail-making, clock drawing, abstraction and delayed recall, so it is more sensitive to mild cognitive impairment.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>BDI-II screens depression, which may be checked too, but it does not assess cognition.</li><li>The Bender test is not a cognitive screener for MCI.</li><li>Raven’s CPM measures non-verbal reasoning, not a broad cognitive screen.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>MoCA: 30 points; below 26 suggests impairment; add 1 point if education is 12 years or less.</li><li>Depression can mimic dementia (‘pseudodementia’) — RINPAS 2024 asked about this.</li><li>JEMAS 2024 asked what the MMSE helps assess.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>10 of them</b> (recent examples: IHBAS 2025, GBU 2025, RML 2024, RINPAS 2024). We recommend you focus on this area."}, {"id": 39, "question": "All of the following are subtests of the Bhatia Battery of Performance Tests of Intelligence, EXCEPT:", "options": ["Porteus Maze", "Pattern Drawing", "Alexander’s Pass-Along", "Kohs’ Block Design"], "correctAnswer": 0, "subject": "Intelligence & ability tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> C. M. Bhatia’s battery (1955) has five subtests: Kohs’ Block Design, Alexander’s Pass-Along, Pattern Drawing, Immediate Memory (for digits) and Picture Construction. The Porteus Maze is not part of it.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Block Design, Pass-Along and Pattern Drawing are all Bhatia subtests.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The Bhatia Battery is for ages about 11–16 and can be used with non-literate children.</li><li>It gives a Performance IQ, not a full-scale IQ.</li><li>The Immediate Memory subtest is the only one with a verbal (digit) element.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — RML 2022. We recommend you keep this area ready."}, {"id": 40, "question": "In psychometrics, a test is considered ‘biased’ against a group mainly when:", "options": ["The test was developed in another country", "Some items are difficult for that group", "That group obtains a lower average score", "It predicts the criterion differently (different regression line) for that group"], "correctAnswer": 3, "subject": "Ethics & legal aspects of testing", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Differences in average scores do not by themselves prove bias — the groups may truly differ on the trait. Psychometric bias means the test works differently for groups, e.g. the same score predicts different job or college performance (differential prediction, Cleary, 1968).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Mean differences alone are not evidence of bias.</li><li>Hard items are not biased unless they function differently for equally able people (differential item functioning).</li><li>Foreign origin alone does not make a test biased, though it needs local norms.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Differential Item Functioning (DIF) examines bias at the item level.</li><li>Culture-fair tests try to reduce cultural loading.</li><li>Indian adaptations (MISIC, Binet–Kamat, Indian TAT) were made to reduce cultural bias.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — IHBAS Paper-II. We recommend you keep this area ready."}, {"id": 41, "question": "The PGI Battery of Brain Dysfunction (PGI-BBD) was developed by:", "options": ["V. V. Kamat", "A. J. Malin", "C. M. Bhatia", "Dwarka Pershad and S. K. Verma"], "correctAnswer": 3, "subject": "Indian tools & disability assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Dwarka Pershad and S. K. Verma developed the PGI-BBD (1990) at PGIMER, Chandigarh. It includes the PGI Memory Scale, Verbal and Performance tests of intelligence, and the Bender Gestalt and Nahor–Benson tests.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Malin – MISIC and the Indian VSMS.</li><li>Bhatia – performance battery of intelligence.</li><li>Kamat – Binet–Kamat test.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The PGI Memory Scale was developed by Pershad and Wig (1977).</li><li>RINPAS 2024 listed the Nahor–Benson Test in a question.</li><li>The NIMHANS Neuropsychological Battery is another widely used Indian battery.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — RINPAS 2024, M.Phil Entrance 2021. We recommend you keep this area ready."}, {"id": 42, "question": "Following Lee Cronbach’s distinction, personality inventories such as the MMPI are best described as measures of:", "options": ["Typical performance", "Aptitude", "Maximal performance", "Achievement"], "correctAnswer": 0, "subject": "History & foundations", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Cronbach divided tests into maximal performance (what a person CAN do at their best — ability tests) and typical performance (what a person USUALLY does — personality, interests, attitudes).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Maximal performance – intelligence, aptitude and achievement tests.</li><li>Aptitude and achievement are both types of maximal-performance tests.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Cronbach also gave coefficient alpha (1951) and, with Meehl, construct validity (1955).</li><li>Cronbach’s book Essentials of Psychological Testing is a classic text.</li><li>Anastasi’s Psychological Testing is the other standard reference.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 43, "question": "V. V. Kamat’s 1934 Indian adaptation (the Binet–Kamat Test) was based on which scale?", "options": ["Raven’s Progressive Matrices", "Stanford–Binet scale", "Wechsler Intelligence Scale for Children", "Porteus Maze Test"], "correctAnswer": 1, "subject": "Intelligence & ability tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> V. V. Kamat adapted the Stanford revision of the Binet scale for Marathi- and Kannada-speaking children in 1934. It remains an important Indian intelligence test, especially for intellectual disability assessment.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>WISC was adapted by Malin (MISIC).</li><li>Raven’s and Porteus are separate non-verbal tests.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Other early Indian adaptations: C. H. Rice’s Hindustani Binet (1930s) and S. M. Mohsin’s Hindi test.</li><li>IMHANS 2021 asked who made the first attempt to standardise mental tests in India.</li><li>Binet-type scales use mental age, so they suit children and people with intellectual disability.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — IMHANS 2021. We recommend you keep this area ready."}, {"id": 44, "question": "Trail Making Test Part B, in which the person alternately connects numbers and letters (1-A-2-B-3-C...), mainly assesses:", "options": ["Simple motor speed only", "Visual recognition of faces", "Cognitive flexibility (set-shifting) and divided attention", "Verbal learning and memory"], "correctAnswer": 2, "subject": "Neuropsychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Part A (numbers only) measures visual scanning and processing speed. Part B adds switching between two sequences, so it taps cognitive flexibility and divided attention — executive functions.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Verbal memory needs word-list tests like the Rey AVLT.</li><li>Motor speed alone is measured by Finger Tapping.</li><li>Face recognition is tested by the Benton Facial Recognition Test.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The B minus A time difference is a purer index of set-shifting.</li><li>TMT was originally part of the Army Individual Test Battery (1944) and is included in the Halstead–Reitan Battery.</li><li>JANAS asked which is NOT a component of executive function.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>3 papers</b> — IHBAS 2025, GBU 2025, JANAS. We recommend you keep this area ready."}, {"id": 45, "question": "The Brief Psychiatric Rating Scale (BPRS, 1962) was developed by:", "options": ["Nancy Andreasen", "Max Hamilton", "Stanley Kay, Abraham Fiszbein and Lewis Opler", "John Overall and Donald Gorham"], "correctAnswer": 3, "subject": "Interviews, MSE & rating scales", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Overall and Gorham created the BPRS in 1962. The common version has 18 items, rated on 7-point scales, for quickly measuring psychotic and other symptoms.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Kay, Fiszbein &amp; Opler – the PANSS (1987).</li><li>Hamilton – rating scales for depression (HAM-D) and anxiety (HAM-A).</li><li>Andreasen – SANS and SAPS.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The BPRS is clinician-rated after a short interview.</li><li>J&amp;K 2023 asked which test assesses symptoms of schizophrenia.</li><li>The PANSS grew partly out of the BPRS items.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 46, "question": "On the Vineland Social Maturity Scale, an 8-year-old child obtains a social age of 6 years. The Social Quotient (SQ) is:", "options": ["48", "75", "80", "133"], "correctAnswer": 1, "subject": "Indian tools & disability assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> SQ = (Social Age ÷ Chronological Age) × 100 = (6 ÷ 8) × 100 = 75.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>133 = CA ÷ SA × 100 (upside down).</li><li>48 and 80 are arithmetic slips.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>JEMAS 2024 asked how to use a VSMS score of 43 to calculate disability.</li><li>Edgar Doll developed the VSMS (1935); A. J. Malin adapted it for India. RML 2022 asked who devised it.</li><li>The VSMS measures adaptive behaviour: self-help, locomotion, occupation, communication, self-direction and socialization.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — JEMAS 2024, RML 2022. We recommend you keep this area ready."}, {"id": 47, "question": "The Differential Aptitude Tests (DAT) and the General Aptitude Test Battery (GATB) are examples of:", "options": ["Multiple aptitude batteries", "Projective tests", "Interest inventories", "Achievement tests"], "correctAnswer": 0, "subject": "Vocational assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Multiple aptitude batteries measure several separate abilities (e.g. verbal reasoning, numerical ability, spatial ability, clerical speed, manual dexterity) to guide career and educational choices.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Achievement tests measure what has already been learned.</li><li>Projective tests assess personality.</li><li>Interest inventories (Strong, Kuder, Holland) measure likes and dislikes, not ability.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>IMHANS 2021 asked which ability is NOT measured by the GATB.</li><li>GMCH 2023 asked which test predicts future performance (aptitude test).</li><li>Aptitude = potential to learn; achievement = past learning.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>7 of them</b> (recent examples: IMHANS 2025, IHBAS 2025, GBU 2025, GMCH 2023). We recommend you focus on this area."}, {"id": 48, "question": "On day 2 of stopping alcohol, an inpatient develops tremors, sweating, nausea and agitation. Nurses rate his symptoms every few hours to decide the dose of benzodiazepines. The scale used is the:", "options": ["CAGE", "MAST", "CIWA-Ar", "AUDIT"], "correctAnswer": 2, "subject": "Clinical assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The Clinical Institute Withdrawal Assessment for Alcohol, revised (CIWA-Ar) has 10 items rating withdrawal severity. It guides symptom-triggered benzodiazepine treatment.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>AUDIT, CAGE and MAST are screening tools for drinking problems, not withdrawal severity.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Wernicke encephalopathy must be prevented with thiamine during detoxification.</li><li>The COWS scale does the same job for opioid withdrawal.</li><li>GMCH 2023 asked about psychological dependence terms in substance use.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — GMCH 2023. We recommend you keep this area ready."}, {"id": 49, "question": "On the Indian Scale for Assessment of Autism (ISAA), a 6-year-old scores 120. This indicates:", "options": ["Moderate autism", "Severe autism", "No autism", "Mild autism"], "correctAnswer": 0, "subject": "Indian tools & disability assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> ISAA (NIMH, 2009) has 40 items rated 1–5, giving totals of 40–200. Cut-offs: below 70 no autism; 70–106 mild; 107–153 moderate; above 153 severe. A score of 120 falls in the moderate range.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>No autism is below 70.</li><li>Mild is 70–106.</li><li>Severe is above 153.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>IHBAS 2024 asked for the Indian tool for autism severity and disability; JEMAS 2024 asked for the full form of ISAA.</li><li>ISAA has six domains, including social relationship and reciprocity, emotional responsiveness, speech-language and communication, behaviour patterns, sensory aspects and the cognitive component.</li><li>Under the RPwD Act 2016, autism spectrum disorder is a specified disability.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>9 of them</b> (recent examples: IHBAS 2025, RINPAS 2024, JEMAS 2024, IHBAS 2024). We recommend you focus on this area."}, {"id": 50, "question": "The clinical scales of the original MMPI were constructed mainly by:", "options": ["Rational–theoretical selection of items based on Freud’s theory", "Empirical criterion keying — keeping items that separated diagnosed patient groups from normal people", "Guttman scaling of items in order of intensity", "Factor analysis of a large pool of trait adjectives"], "correctAnswer": 1, "subject": "Objective personality tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Hathaway and McKinley (1943) kept any item that patients with a given diagnosis answered differently from normal people — whatever the item’s content. This is empirical criterion keying.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Factor analysis built the 16PF and the NEO, not the MMPI.</li><li>Rational–theoretical construction is used in tests like the MCMI (Millon’s theory).</li><li>Guttman scaling is used in attitude measurement.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The MMPI was made by psychologist Starke Hathaway and neurologist J. C. McKinley at the University of Minnesota.</li><li>JEMAS 2022 and IHBAS 2025 asked what the MMPI measures; JANAS asked how many clinical scales it has (10).</li><li>IMHANS 2021 asked which inventories are NOT factor-analytically derived.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>11 of them</b> (recent examples: IHBAS 2025, RINPAS 2024, IHBAS 2024, GMCH 2023). We recommend you focus on this area."}, {"id": 51, "question": "The SORKC model of behavioural assessment (Stimulus–Organism–Response–Contingency–Consequence) is associated with:", "options": ["Arnold Lazarus", "Joseph Wolpe", "Frederick Kanfer (with George Saslow)", "B. F. Skinner"], "correctAnswer": 2, "subject": "Behavioural assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Frederick Kanfer and George Saslow (1965) proposed ‘behavioural diagnosis’ as an alternative to traditional psychiatric diagnosis. Kanfer’s SORKC model adds organismic (biological) variables and the schedule (contingency) of reinforcement to the simple ABC.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Lazarus – the multimodal BASIC ID assessment.</li><li>Skinner – the three-term contingency (A-B-C).</li><li>Wolpe – systematic desensitization and SUDS.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Behavioural assessment focuses on current, observable behaviour and its controlling variables.</li><li>Methods: direct observation, self-monitoring, analogue observation (IMHANS 2021), behavioural interviews.</li><li>Functional analysis links assessment directly to treatment.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — IMHANS 2021. We recommend you keep this area ready."}, {"id": 52, "question": "Arrange these milestones in intelligence testing in chronological order: I. Binet–Simon scale II. Army Alpha and Army Beta III. Stern’s ‘mental quotient’ IV. Wechsler–Bellevue scale", "options": ["I, II, III, IV", "III, I, II, IV", "I, III, IV, II", "I, III, II, IV"], "correctAnswer": 3, "subject": "History & foundations", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Binet–Simon scale (1905) → William Stern’s mental quotient, MA ÷ CA (1912) → Army Alpha and Beta (1917) → Wechsler–Bellevue (1939).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The other orders place the army tests before Stern, or Wechsler before the army tests.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Lewis Terman multiplied Stern’s quotient by 100 and popularised ‘IQ’ in the Stanford–Binet (1916). JEMAS 2022/2024 and JANAS asked who invented the term IQ (Stern).</li><li>NFSU 2023 asked when the first Wechsler scale appeared (1939).</li><li>Wechsler replaced ratio IQ with deviation IQ (mean 100, SD 15).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>6 of them</b> (recent examples: JEMAS 2024, NFSU 2023, JEMAS 2022, M.Phil Entrance 2021). We recommend you focus on this area."}, {"id": 53, "question": "The Rorschach Performance Assessment System (R-PAS, 2011) changed standard administration mainly by:", "options": ["Dropping the inquiry phase completely", "Scoring only the colour cards", "Asking for two or three responses per card (‘R-optimized’ administration)", "Replacing the inkblots with photographs"], "correctAnswer": 2, "subject": "Projective tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Too few or too many responses distort Rorschach scores. R-PAS (Meyer, Viglione, Mihura, Erard and Erdberg) asks for ‘two, maybe three’ responses per card, with prompts and pulls, so the total is more stable.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>R-PAS still uses the same 10 original blots.</li><li>Clarification (inquiry) is still done.</li><li>All ten cards are scored.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>R-PAS is the main successor to Exner’s Comprehensive System.</li><li>It uses standard scores based on international norms.</li><li>Newer versions of classic tests are an ‘outlier’ area in recent NIMHANS and IHBAS papers.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>8 of them</b> (recent examples: GBU 2025, RINPAS 2024, IHBAS 2024, GMCH 2023). We recommend you focus on this area."}, {"id": 54, "question": "In a drug trial, a trained clinician interviews each depressed patient and rates 17 items such as guilt, insomnia, agitation and weight loss. The instrument being used is the:", "options": ["Hamilton Depression Rating Scale (HAM-D)", "Beck Depression Inventory-II (BDI-II)", "Patient Health Questionnaire (PHQ-9)", "Geriatric Depression Scale (GDS)"], "correctAnswer": 0, "subject": "Interviews, MSE & rating scales", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The HAM-D (Max Hamilton, 1960) is a clinician-rated scale; the original version has 17 items. It is the classic outcome measure in antidepressant trials.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>BDI-II – 21-item self-report.</li><li>PHQ-9 – 9-item self-report screener.</li><li>GDS – self-report for older adults.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Clinician-rated vs self-report is a favourite distinction.</li><li>The Montgomery–Åsberg scale (MADRS) is another clinician-rated depression scale.</li><li>HAM-A (14 items) is Hamilton’s anxiety scale.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — RML 2022. We recommend you keep this area ready."}, {"id": 55, "question": "Arrange the phases of Rorschach administration in the correct order: I. Inquiry phase II. Response (free-association) phase III. Testing the limits", "options": ["I, II, III", "II, III, I", "III, II, I", "II, I, III"], "correctAnswer": 3, "subject": "Projective tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> First the person tells what each card could be (response phase). Then the examiner goes through the cards again, asking where and what made it look that way (inquiry). Testing the limits is optional and comes last, to check whether the person can see popular responses.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Inquiry cannot come before responses exist.</li><li>Testing the limits must come after the scored phases so that it does not contaminate them.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>GBU 2025 asked what the Enquiry phase is.</li><li>John Exner’s Comprehensive System (1974) combined earlier scoring systems (Beck, Klopfer, Hertz, Piotrowski, Rapaport).</li><li>Seating: the examiner sits beside, not opposite, the person to avoid cueing.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>8 of them</b> (recent examples: GBU 2025, RINPAS 2024, IHBAS 2024, GMCH 2023). We recommend you focus on this area."}, {"id": 56, "question": "The Positive and Negative Syndrome Scale (PANSS) has 30 items divided as:", "options": ["5 positive, 5 negative and 20 general items", "7 positive, 7 negative and 16 general psychopathology items", "15 positive and 15 negative items", "10 positive, 10 negative and 10 general items"], "correctAnswer": 1, "subject": "Interviews, MSE & rating scales", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The PANSS (Kay, Fiszbein &amp; Opler, 1987) has 7 positive, 7 negative and 16 general psychopathology items, each rated 1–7, so totals range from 30 to 210.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The other splits are invented.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The PANSS is the most widely used outcome scale in schizophrenia trials.</li><li>IHBAS 2025 asked for a negative symptom of schizophrenia (e.g. flat affect).</li><li>Andreasen’s SANS and SAPS measure negative and positive symptoms separately.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — IHBAS 2025. We recommend you keep this area ready."}, {"id": 57, "question": "A 10-year-old girl with average intelligence reads two years below her grade level and makes frequent spelling reversals. To diagnose a specific learning disability, clinicians in India most commonly use the:", "options": ["Childhood Autism Rating Scale", "NIMHANS Index for Specific Learning Disabilities", "Indian Scale for Assessment of Autism", "Vineland Social Maturity Scale"], "correctAnswer": 1, "subject": "Developmental & child assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The NIMHANS SLD Index (Kapur, Hirisave and colleagues) tests reading, writing, spelling, maths and related skills, graded by school level. It is widely used in India to identify dyslexia, dysgraphia and dyscalculia.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>ISAA and CARS are for autism.</li><li>VSMS measures social maturity.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>GBU 2025 asked about dyslexia, dyscalculia and learning-difficulty interventions.</li><li>Specific learning disability is one of the 21 specified disabilities under the RPwD Act 2016.</li><li>DSM-5-TR: SLD persists for at least 6 months despite targeted help.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>6 of them</b> (recent examples: GBU 2025, IHBAS 2024, JEMAS 2022, M.Phil Entrance 2021). We recommend you focus on this area."}, {"id": 58, "question": "A 6-year-old child who speaks little English is asked to draw a man. The psychologist scores the drawing by counting details such as eyes, fingers, clothing and proportion, to estimate intellectual maturity. The test being used is the:", "options": ["Goodenough–Harris Draw-a-Man test", "Bender Visual Motor Gestalt Test", "House–Tree–Person test", "Machover Draw-a-Person test"], "correctAnswer": 0, "subject": "Intelligence & ability tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Florence Goodenough (1926) scored children’s drawings of a man for detail as a non-verbal estimate of intelligence. Dale Harris revised it in 1963.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Machover’s DAP (1949) is a projective personality test — it interprets features emotionally, not by counting details.</li><li>HTP (Buck, 1948) is also projective.</li><li>The Bender test involves copying designs, not free drawing.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Goodenough vs Machover is a classic look-alike trap: same drawing, different purpose.</li><li>Drawing tests are culture-reduced and need no reading.</li><li>Gurugram asked which is NOT a projective test.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — RML 2022, IMHANS 2021. We recommend you keep this area ready."}, {"id": 59, "question": "All of the following are part of the Halstead–Reitan Neuropsychological Battery, EXCEPT:", "options": ["Category Test", "Tactual Performance Test", "Wisconsin Card Sorting Test", "Finger Tapping Test"], "correctAnswer": 2, "subject": "Neuropsychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The Halstead–Reitan Battery includes the Category Test, Tactual Performance Test, Seashore Rhythm Test, Speech-Sounds Perception Test, Finger Tapping Test and Trail Making Test. The WCST is a separate test.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Category, Tactual Performance and Finger Tapping are all core Halstead–Reitan tests.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The Halstead Impairment Index summarises performance across tests.</li><li>The Luria–Nebraska Battery (Golden) is the other classic fixed battery — M.Phil Entrance 2021 asked how many clinical scales it has.</li><li>Fixed batteries vs flexible, process-based testing is a common concept question.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — M.Phil Entrance 2021. We recommend you keep this area ready."}, {"id": 60, "question": "Under the Rehabilitation Council of India Act, 1992, a clinical psychologist in India must be:", "options": ["Licensed by the National Medical Commission", "Registered with the Mental Health Review Board", "A member of the Indian Psychiatric Society", "Registered in the Central Rehabilitation Register maintained by RCI"], "correctAnswer": 3, "subject": "Ethics & legal aspects of testing", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The RCI Act makes it an offence for anyone without a recognised qualification and registration in the Central Rehabilitation Register (CRR) to practise as a rehabilitation professional, which includes clinical psychologists.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The NMC licenses doctors, not psychologists.</li><li>IPS membership is for psychiatrists and is voluntary.</li><li>Mental Health Review Boards oversee admissions and rights under MHCA 2017; they do not register psychologists.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>JEMAS 2022 asked about the body regulating training in disability rehabilitation (RCI Act 1992).</li><li>The RCI Act was amended in 2000.</li><li>The Mental Healthcare Act 2017 recognises clinical psychologists with RCI-recognised qualifications as mental health professionals.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — JEMAS 2022. We recommend you keep this area ready."}, {"id": 61, "question": "Card 16 of the Thematic Apperception Test is unique because it:", "options": ["Shows a family scene and is given only to children", "Is the only coloured card in the set", "Is completely blank, and the person imagines a picture and tells a story about it", "Is used only to measure intelligence"], "correctAnswer": 2, "subject": "Projective tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Card 16 is the blank card. The person creates both the picture and the story, so it is the most unstructured stimulus in the set.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The TAT cards are all black-and-white drawings, and none is used only for children.</li><li>The TAT is a personality (projective) test, not an intelligence test.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Some TAT cards are meant for boys, girls, men or women (marked B, G, M, F).</li><li>The TAT is a ‘construction’ technique in Lindzey’s scheme.</li><li>GMCH 2023 and GBU 2025 asked what the TAT measures and how it differs from the Rorschach.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>8 of them</b> (recent examples: IHBAS 2025, GBU 2025, IHBAS 2024, GMCH 2023). We recommend you focus on this area."}, {"id": 62, "question": "All of the following are index scores of the WAIS-IV, EXCEPT:", "options": ["Verbal Comprehension Index", "Processing Speed Index", "Perceptual Reasoning Index", "Fluid Reasoning Index"], "correctAnswer": 3, "subject": "Intelligence & ability tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The WAIS-IV (2008) has four indexes: Verbal Comprehension, Perceptual Reasoning, Working Memory and Processing Speed. A separate Fluid Reasoning Index appears in the WISC-V (2014) and the WAIS-5 (2024).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>VCI, PRI and PSI are all genuine WAIS-IV indexes.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>JEMAS 2024 asked about WAIS-IV index scales and the Symbol Search subtest (Processing Speed).</li><li>WAIS-IV has 10 core and 5 supplementary subtests, for ages 16–90.</li><li>Older Wechsler scales gave Verbal IQ and Performance IQ (Gurugram asked this).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>6 of them</b> (recent examples: IMHANS 2025, IHBAS 2025, GBU 2025, JEMAS 2024). We recommend you focus on this area."}, {"id": 63, "question": "An Indian modification of the Thematic Apperception Test (1960) was developed by:", "options": ["Durganand Sinha", "Uma Chowdhury", "S. M. Mohsin", "Udai Pareek"], "correctAnswer": 1, "subject": "Projective tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Uma Chowdhury published ‘An Indian Modification of the Thematic Apperception Test’ in 1960. The cards show Indian figures and settings, making the stories more culturally meaningful.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Udai Pareek – organisational psychology and Indian adaptations of other tests.</li><li>Durganand Sinha – Indian psychology and development.</li><li>S. M. Mohsin – an early Hindi intelligence test.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The TAT was created by Christiana Morgan and Henry Murray (1935) — GBU 2025 asked who developed it and in which decade.</li><li>The full TAT has 31 cards; usually about 10–12 are used in a session (GBU 2025).</li><li>Stories are scored for needs, press, themes and outcomes.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>8 of them</b> (recent examples: IHBAS 2025, GBU 2025, IHBAS 2024, GMCH 2023). We recommend you focus on this area."}, {"id": 64, "question": "A 9-year-old boy in Maharashtra is referred for poor school performance. The psychologist needs a full-scale IQ with separate verbal and performance subtests, normed on Indian children. The best choice is:", "options": ["Malin’s Intelligence Scale for Indian Children (MISIC)", "Bhatia Battery of Performance Tests", "Raven’s Standard Progressive Matrices", "WAIS-IV"], "correctAnswer": 0, "subject": "Intelligence & ability tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> MISIC (A. J. Malin, 1969) is the Indian adaptation of the WISC for ages about 6–15. It gives Verbal, Performance and Full-scale IQs from Indian norms.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Bhatia Battery – performance only, for about 11–16 years.</li><li>WAIS-IV – for adults aged 16–90.</li><li>Raven’s SPM – a single non-verbal g measure, no verbal subtests.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>RML 2022 asked at what age MISIC can be given.</li><li>MISIC verbal subtests: Information, Comprehension, Arithmetic, Similarities, Vocabulary, Digit Span; performance: Picture Completion, Block Design, Object Assembly, Coding, Mazes.</li><li>Malin also adapted the Vineland Social Maturity Scale for India.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — RML 2022. We recommend you keep this area ready."}, {"id": 65, "question": "During World War I, US recruits who could not read English were tested using pictures, mazes and demonstrations instead of written instructions. This test was the:", "options": ["Army Alpha", "Army Beta", "Wechsler–Bellevue", "Stanford–Binet"], "correctAnswer": 1, "subject": "History & foundations", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Robert Yerkes’ committee (1917) created two group tests: Army Alpha (verbal, for literate recruits) and Army Beta (non-verbal, for illiterate or non-English speakers).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Army Alpha – the written, verbal version.</li><li>Stanford–Binet – an individual test for children.</li><li>Wechsler–Bellevue – came later, in 1939.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>These were the first large-scale group intelligence tests.</li><li>JEMAS 2022 asked about clinical psychology’s main contribution in World War I (group testing).</li><li>Wechsler worked with army testing and later used Beta-type tasks in his performance scale.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — JEMAS 2022. We recommend you keep this area ready."}, {"id": 66, "question": "The Boston ‘process approach’ to neuropsychological assessment, associated with Edith Kaplan, emphasises:", "options": ["Measuring only overall IQ", "Interpreting responses symbolically, as in projective tests", "How the patient arrives at an answer — qualitative errors and strategies — using flexible test selection", "Giving the same fixed battery to every patient and relying only on cut-off scores"], "correctAnswer": 2, "subject": "Neuropsychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Kaplan argued that two patients with the same score may fail for very different reasons. The process approach looks at the strategy and types of error, and chooses tests to fit the referral question.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>A fixed battery with cut-offs describes Halstead–Reitan-style testing.</li><li>IQ alone misses specific deficits.</li><li>Symbolic interpretation belongs to projective testing.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>GBU 2025 asked about the ‘ideometric’ approach in neuropsychological assessment.</li><li>The WAIS-R NI (Neuropsychological Instrument) was a Kaplan process-based version.</li><li>Most clinicians today use a flexible, hypothesis-testing battery.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — GBU 2025. We recommend you keep this area ready."}, {"id": 67, "question": "Match the clinical scale (List I) with what it measures (List II): Codes:<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>List I</th><th>List II</th></tr></thead><tbody><tr><td>1. Beck Hopelessness Scale</td><td>a. Depression after childbirth</td></tr><tr><td>2. Hamilton Anxiety Rating Scale</td><td>b. Clinician-rated anxiety severity</td></tr><tr><td>3. Edinburgh Postnatal Depression Scale</td><td>c. Depression screening in primary care</td></tr><tr><td>4. PHQ-9</td><td>d. Negative expectations about the future (suicide risk)</td></tr></tbody></table></div>", "options": ["1-d, 2-b, 3-a, 4-c", "1-b, 2-d, 3-a, 4-c", "1-d, 2-a, 3-b, 4-c", "1-d, 2-b, 3-c, 4-a"], "correctAnswer": 0, "subject": "Clinical assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Beck Hopelessness Scale (20 true–false items) → pessimism about the future, a strong suicide-risk marker. HAM-A (14 items) → clinician-rated anxiety. EPDS (10 items) → postnatal depression. PHQ-9 → nine DSM depression symptoms, used in primary care.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The other codes swap the two depression scales or the anxiety and hopelessness scales.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Beck’s cognitive triad (JEMAS 2022, JEPAS 2020) includes a negative view of the future — the idea behind the Hopelessness Scale.</li><li>Other Beck scales: BDI-II (21 items), BAI (21 items), Beck Scale for Suicide Ideation.</li><li>The PHQ-2 uses just the first two items as a quick screen.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>4 papers</b> — JEMAS 2024, RML 2022, JEMAS 2022, JEPAS 2020. We recommend you keep this area ready."}, {"id": 68, "question": "A 35-year-old man with a 10-year history of schizophrenia applies for a disability certificate. The psychiatrist rates his self-care, interpersonal activities, communication and understanding, and work, plus the duration of illness. The instrument used in India for this is:", "options": ["PGI Battery of Brain Dysfunction", "ISAA", "Vineland Social Maturity Scale", "IDEAS (Indian Disability Evaluation and Assessment Scale)"], "correctAnswer": 3, "subject": "Indian tools & disability assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> IDEAS is the government-recommended tool for certifying disability due to mental illness in India. It scores four areas of functioning and adds a score for duration of illness.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>ISAA is for autism.</li><li>VSMS is for social maturity in children (intellectual disability).</li><li>PGI-BBD assesses brain dysfunction, not disability percentage.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Mental illness is one of the 21 specified disabilities under the RPwD Act 2016.</li><li>‘Benchmark disability’ means at least 40%.</li><li>IHBAS 2024 asked about the minimum age for assessment under the RPwD Act.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — IHBAS 2024, JEMAS 2022. We recommend you keep this area ready."}, {"id": 69, "question": "Which Wechsler scale, published in 2024, split the adult Perceptual Reasoning Index into separate Visual Spatial and Fluid Reasoning indexes, giving five primary index scores?", "options": ["WAIS-5", "WISC-V", "WPPSI-IV", "WAIS-IV"], "correctAnswer": 0, "subject": "Intelligence & ability tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The WAIS-5 (2024) brought the adult scale in line with the WISC-V structure: Verbal Comprehension, Visual Spatial, Fluid Reasoning, Working Memory and Processing Speed. It also added new subtests such as Running Digits and Symbol Span.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>WAIS-IV has four indexes including Perceptual Reasoning.</li><li>WISC-V (2014) has the five-index model, but it is for children aged 6–16.</li><li>WPPSI-IV is for young children (21⁄2–71⁄2 years).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>WAIS-5 has 10 primary subtests and a shorter FSIQ administration (about 45 minutes).</li><li>Newer editions come with updated norms — examiners like ‘latest version’ questions.</li><li>IMHANS 2025 asked how the WAIS measures intelligence (through index scores).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>12 of them</b> (recent examples: IMHANS 2025, IHBAS 2025, GBU 2025, RINPAS 2024). We recommend you focus on this area."}, {"id": 70, "question": "The Edwards Personal Preference Schedule (EPPS) uses a forced-choice format mainly to control for:", "options": ["Order effects", "Fatigue effects", "Acquiescence", "Social desirability"], "correctAnswer": 3, "subject": "Objective personality tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> In the EPPS (1953), each pair of statements is matched for social desirability. The person must choose one, so they cannot simply pick the ‘nicer-sounding’ answer.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Acquiescence is controlled by balanced (reverse-keyed) items.</li><li>Fatigue and order effects are not the main target.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The EPPS measures 15 needs taken from Henry Murray’s list.</li><li>Forced choice makes the scores ipsative — they compare needs within the person, not across people.</li><li>IMHANS 2021 listed the EPPS among inventories in a factor-analysis question.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>3 papers</b> — RML 2024, IMHANS 2021, JANAS. We recommend you keep this area ready."}, {"id": 71, "question": "Scores on an M.Psy entrance test are correlated with the same students’ marks at the end of their first year of the course. This establishes the test’s:", "options": ["Face validity", "Predictive validity", "Concurrent validity", "Content validity"], "correctAnswer": 1, "subject": "Reliability, validity & norms", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Predictive validity is shown when test scores predict a criterion measured later (here, first-year marks).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Concurrent validity – the criterion is measured at about the same time.</li><li>Content validity – items represent the whole content domain.</li><li>Face validity – the test looks as if it measures the right thing.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Predictive and concurrent validity are both types of criterion-related validity.</li><li>IMHANS 2021 asked which statement describes concurrent validity.</li><li>Criterion contamination: when the criterion is influenced by knowledge of test scores.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>5 papers</b> — RML 2024, RINPAS 2024, IMHANS 2021, IHBAS Paper-II, Gurugram. We recommend you keep this area ready."}, {"id": 72, "question": "Five-year-old Tanvi will not talk about her family. The psychologist shows her pictures of animals — bears, chicks and monkeys — in human-like family situations and asks her to tell a story about each. The test being used is:", "options": ["Rorschach Inkblot Test", "Thematic Apperception Test (TAT)", "Children’s Apperception Test (CAT)", "Rosenzweig Picture-Frustration Study"], "correctAnswer": 2, "subject": "Projective tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The CAT (Leopold and Sonya Bellak, 1949) uses animal figures because young children identify with animals more easily than with human figures. Children aged about 3–10 tell stories about each picture.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The TAT uses human figures and suits older children and adults.</li><li>The Rorschach uses inkblots, not pictures of scenes.</li><li>The Rosenzweig uses cartoon frustration scenes with speech bubbles.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>CAT-H uses human figures; the Senior Apperception Test (SAT) is for older adults.</li><li>Other child projectives: the Blacky Pictures (Blum) and Michigan Picture Test.</li><li>Apperception tests are ‘construction’ techniques.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>6 of them</b> (recent examples: GBU 2025, IHBAS 2024, GMCH 2023, RML 2022). We recommend you focus on this area."}, {"id": 73, "question": "While preparing a final exam on ‘learning theories’, a teacher makes sure every unit is covered by questions in proportion to the time spent teaching it, and asks two senior teachers to review the items. She is mainly ensuring:", "options": ["Test–retest reliability", "Construct validity", "Content validity", "Predictive validity"], "correctAnswer": 2, "subject": "Reliability, validity & norms", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Content validity means the items adequately and representatively sample the whole domain. It is built with a table of specifications (blueprint) and checked by expert judgement.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Construct validity – whether the test measures a theoretical trait, shown through correlations and factor analysis.</li><li>Predictive validity – prediction of a later criterion.</li><li>Test–retest – stability of scores over time.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Content validity is most important for achievement tests.</li><li>Face validity is how the test looks to test-takers — not a technical form of validity.</li><li>GBU 2025 asked what best represents construct validity.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>5 papers</b> — GBU 2025, NFSU 2023, RML 2022, IHBAS Paper-II, Gurugram. We recommend you keep this area ready."}, {"id": 74, "question": "Read the Assertion (A) and Reason (R) and choose the correct option: Assertion (A): DSM-5 specifies the severity of intellectual disability mainly by adaptive functioning rather than IQ score. Reason (R): IQ tests are less valid at the lower end of the IQ range, and adaptive functioning decides the level of support needed.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is NOT the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "correctAnswer": 0, "subject": "Indian tools & disability assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Both are true, and R explains A. DSM-5 defines mild, moderate, severe and profound levels by functioning in conceptual, social and practical domains. It notes that IQ scores are less valid at the low end and that adaptive functioning determines needed supports.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>R gives DSM-5’s own reasons, so B is wrong.</li><li>C and D are wrong because both statements are true.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>ICD-10 IQ bands: mild 50–69, moderate 35–49, severe 20–34, profound below 20.</li><li>DSM-5 replaced ‘mental retardation’ with ‘intellectual disability (intellectual developmental disorder)’.</li><li>IMHANS 2021 asked about the DSM-IV-TR criterion for mental retardation; JEMAS 2022 asked about NIMH IQ classification.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>4 papers</b> — RML 2022, JEMAS 2022, M.Phil Entrance 2021, IMHANS 2021. We recommend you keep this area ready."}, {"id": 75, "question": "Match the WAIS-IV subtest (List I) with the index it belongs to (List II): Codes:<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>List I</th><th>List II</th></tr></thead><tbody><tr><td>1. Arithmetic</td><td>a. Verbal Comprehension</td></tr><tr><td>2. Matrix Reasoning</td><td>b. Working Memory</td></tr><tr><td>3. Coding</td><td>c. Processing Speed</td></tr><tr><td>4. Similarities</td><td>d. Perceptual Reasoning</td></tr></tbody></table></div>", "options": ["1-d, 2-b, 3-c, 4-a", "1-b, 2-d, 3-c, 4-a", "1-b, 2-d, 3-a, 4-c", "1-c, 2-d, 3-b, 4-a"], "correctAnswer": 1, "subject": "Intelligence & ability tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Arithmetic → Working Memory (with Digit Span); Matrix Reasoning → Perceptual Reasoning (with Block Design and Visual Puzzles); Coding → Processing Speed (with Symbol Search); Similarities → Verbal Comprehension (with Vocabulary and Information).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The other codes wrongly place Arithmetic under Perceptual Reasoning or Coding under Working Memory.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Symbol Search is in the Processing Speed Index — asked in JEMAS 2024.</li><li>Supplementary WAIS-IV subtests: Comprehension, Figure Weights, Letter–Number Sequencing, Picture Completion, Cancellation.</li><li>NFSU 2023 asked which is NOT a performance subtest of the WAIS-III.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>12 of them</b> (recent examples: IMHANS 2025, IHBAS 2025, GBU 2025, RINPAS 2024). We recommend you focus on this area."}, {"id": 76, "question": "Under the APA Ethics Code (Standard 9.03), informed consent for assessment is NOT required when:", "options": ["The test takes less than 30 minutes", "The client is an adult", "The client is a student", "Testing is mandated by law or by a court order"], "correctAnswer": 3, "subject": "Ethics & legal aspects of testing", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Consent is not needed when testing is required by law or government regulation, when it is implied (e.g. routine school or job testing), or when the purpose is to evaluate decisional capacity. In court-ordered testing, the person must still be told about the nature and purpose of the assessment.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Being an adult or a student does not remove the need for consent.</li><li>Test length is irrelevant.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Informed consent is one of the basic rules of research ethics (NFSU 2023, GBU 2025).</li><li>The Mental Healthcare Act 2017 also stresses capacity and consent.</li><li>The RCI code of conduct expects consent and confidentiality from registered professionals.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>4 papers</b> — IHBAS 2025, GBU 2025, NFSU 2023, JEPAS 2020. We recommend you keep this area ready."}, {"id": 77, "question": "On the Child Behavior Checklist filled in by her mother, 9-year-old Riya scores high on the anxious/depressed, withdrawn/depressed and somatic complaints scales. These scales together form the:", "options": ["Attention problems scale", "Total competence scale", "Internalizing problems scale", "Externalizing problems scale"], "correctAnswer": 2, "subject": "Clinical assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> In Thomas Achenbach’s system, anxious/depressed, withdrawn/depressed and somatic complaints make up internalizing problems — difficulties directed inward.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Externalizing = rule-breaking and aggressive behaviour.</li><li>Competence scales measure activities, social life and school.</li><li>Attention problems is a separate syndrome scale.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The ASEBA system includes the CBCL (parent), TRF (teacher) and YSR (youth self-report).</li><li>Internalizing vs externalizing is a key way to classify childhood problems.</li><li>JEMAS 2022 asked about treatment of childhood anxiety and about conduct disorder in adolescence.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>4 papers</b> — JEMAS 2024, IHBAS 2024, JEMAS 2022, JEPAS 2020. We recommend you keep this area ready."}, {"id": 78, "question": "Cattell’s Culture Fair Intelligence Test was designed mainly to measure:", "options": ["Divergent (creative) thinking", "Fluid intelligence, with minimal cultural and verbal content", "Crystallized intelligence through vocabulary", "Emotional intelligence"], "correctAnswer": 1, "subject": "Intelligence & ability tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Raymond Cattell built this test of non-verbal puzzles (series, classification, matrices) to reduce the influence of language, schooling and culture, so that it taps fluid intelligence.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Vocabulary is crystallized and culture-loaded.</li><li>Emotional intelligence was defined later (Salovey &amp; Mayer, 1990).</li><li>Divergent thinking is Guilford’s idea (JANAS asked this).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>No test is fully culture-free; ‘culture-fair’ or ‘culture-reduced’ is the accurate term.</li><li>The Raven’s matrices are also used as culture-reduced tests.</li><li>Horn &amp; Cattell’s fluid–crystallized theory is heavily asked in this area.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — IHBAS Paper-II. We recommend you keep this area ready."}, {"id": 79, "question": "Read the Assertion (A) and Reason (R) and choose the correct option: Assertion (A): Objective personality inventories are quick to score and usually show high reliability. Reason (R): Objective inventories are immune to faking and response distortion.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is NOT the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "correctAnswer": 2, "subject": "Objective personality tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> A is true: fixed answer formats make scoring objective and reliable. R is false: people can fake good or bad on self-report inventories. That is exactly why tests like the MMPI include validity scales.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>A and B are wrong because R is false.</li><li>D is wrong because A is true.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Projective tests are harder to fake but have weaker reliability and validity.</li><li>GBU 2025 asked the main advantage of projective tests (they avoid the limits of self-report).</li><li>Social desirability scales (e.g. Marlowe–Crowne) detect ‘faking good’.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>13 of them</b> (recent examples: IMHANS 2025, IHBAS 2025, GBU 2025, RML 2024). We recommend you focus on this area."}, {"id": 80, "question": "A psychologist gives a 40-item true/false knowledge test once to 200 students and wants to estimate its internal consistency. The most appropriate formula is:", "options": ["Kuder–Richardson Formula 20 (KR-20)", "Parallel-forms correlation", "Test–retest correlation", "Cohen’s kappa"], "correctAnswer": 0, "subject": "Reliability, validity & norms", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> KR-20 (Kuder &amp; Richardson, 1937) estimates internal consistency for items scored right/wrong (dichotomous), from a single administration.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Test–retest needs two administrations.</li><li>Cohen’s kappa is for agreement between two raters.</li><li>Parallel forms needs a second, equivalent form.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Cronbach’s alpha (1951) is the general version that also works for Likert-type items (JEMAS 2024, RINPAS 2024, IHBAS 2025 asked what alpha measures).</li><li>KR-21 is a simpler version that assumes all items are equally difficult.</li><li>Alpha is the average of all possible split-half coefficients (IHBAS Paper-II).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>5 papers</b> — IMHANS 2025, IHBAS 2025, RINPAS 2024, IMHANS 2021, IHBAS Paper-II. We recommend you keep this area ready."}, {"id": 81, "question": "The NEO Five-Factor Inventory (NEO-FFI), the short form of the NEO Personality Inventory, contains:", "options": ["60 items", "120 items", "185 items", "240 items"], "correctAnswer": 0, "subject": "Objective personality tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The NEO-FFI has 60 items — 12 for each of the five domains. It gives domain scores only, not the 30 facet scores.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>240 items is the full NEO-PI-R / NEO-PI-3.</li><li>185 items is the 16PF fifth edition.</li><li>120 items matches some short IPIP versions.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Authors: Paul Costa and Robert McCrae.</li><li>GBU 2025, JEMAS 2024 and RINPAS 2024 asked about the Big Five traits.</li><li>The Big Five is also called OCEAN: Openness, Conscientiousness, Extraversion, Agreeableness, Neuroticism.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>9 of them</b> (recent examples: GBU 2025, RINPAS 2024, JEMAS 2024, NFSU 2023). We recommend you focus on this area."}, {"id": 82, "question": "The Denver Developmental Screening Test (1967) was developed by:", "options": ["Nancy Bayley", "Arnold Gesell and Catherine Amatruda", "Edgar Doll", "William Frankenburg and Josiah Dodds"], "correctAnswer": 3, "subject": "Developmental & child assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Frankenburg and Dodds created the Denver test to screen children from birth to 6 years in four areas: personal-social, fine motor-adaptive, language and gross motor. It was revised as the Denver II (1992).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Gesell and Amatruda – developmental schedules and diagnosis.</li><li>Bayley – infant development scales.</li><li>Doll – Vineland Social Maturity Scale.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Screening instruments flag risk; diagnostic tests confirm it.</li><li>The Indian counterpart is Bharat Raj’s Developmental Screening Test.</li><li>Ages &amp; Stages Questionnaires (ASQ) are parent-completed screeners.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 83, "question": "To measure how severe a patient’s obsessions and compulsions are, and to track change during exposure and response prevention, the clinician should use the:", "options": ["Mini-Mental State Examination", "Hamilton Anxiety Rating Scale", "AUDIT", "Yale–Brown Obsessive Compulsive Scale (Y-BOCS)"], "correctAnswer": 3, "subject": "Interviews, MSE & rating scales", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The Y-BOCS (Goodman et al., 1989) rates obsessions and compulsions separately: 10 items, total 0–40. It is the standard severity and outcome measure for OCD.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>HAM-A measures general anxiety.</li><li>MMSE screens cognition.</li><li>AUDIT screens alcohol use.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>CY-BOCS is the children’s version.</li><li>ERP for OCD was asked in JEMAS 2024, RML 2024 and NFSU 2023.</li><li>A Y-BOCS score of about 16 or above usually indicates clinically significant OCD.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>7 of them</b> (recent examples: IHBAS 2025, RML 2024, JEMAS 2024, IHBAS 2024). We recommend you focus on this area."}, {"id": 84, "question": "Read the Assertion (A) and Reason (R) and choose the correct option: Assertion (A): The ratio IQ (MA/CA × 100) is unsuitable for testing adults. Reason (R): Mental age stops increasing steadily after mid-adolescence, while chronological age keeps rising.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is NOT the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "correctAnswer": 0, "subject": "History & foundations", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Both are true, and R explains A. If mental age levels off at about 15–16 while age keeps rising, a normal 40-year-old would get an absurdly low ratio IQ. That is why Wechsler introduced the deviation IQ, which compares a person with others of the same age.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>B is wrong because R is exactly the reason A is true.</li><li>C and D are wrong because both statements are true.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Deviation IQ = 100 + 15z (mean 100, SD 15). It was repeatedly asked in JEMAS 2022, JEMAS 2024, JANAS and JEPAS 2020.</li><li>Ratio IQ numericals appeared in M.Phil Entrance 2021 and IMHANS 2021.</li><li>The Stanford–Binet also moved to deviation IQs in 1960.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>7 of them</b> (recent examples: JEMAS 2024, RML 2022, JEMAS 2022, M.Phil Entrance 2021). We recommend you focus on this area."}, {"id": 85, "question": "In a driving-licence test, a candidate passes if they correctly complete 90% of set manoeuvres, regardless of how other candidates perform. This is a:", "options": ["Projective test", "Criterion-referenced test", "Ipsative test", "Norm-referenced test"], "correctAnswer": 1, "subject": "Reliability, validity & norms", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> A criterion-referenced test compares a person with a fixed standard of mastery (Robert Glaser, 1963), not with other people.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Norm-referenced – compares a person with a norm group (e.g. percentiles, IQ).</li><li>Ipsative – compares a person’s traits with their own other traits (forced-choice formats).</li><li>Projective – ambiguous stimuli for personality.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Most intelligence and personality tests are norm-referenced.</li><li>Norms must be recent and representative; outdated norms inflate IQ (the Flynn effect).</li><li>NFSU 2023 asked why IQ reports from two different tests are not directly comparable.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this exact point hasn't appeared directly, but it sits right next to frequently asked topics — we recommend a quick revision."}, {"id": 86, "question": "A 70-year-old retired teacher with suspected dementia scores in the average range on Vocabulary and Information, but very low on Digit Symbol (Coding) and Block Design. The clinician uses this contrast to estimate:", "options": ["Test–retest reliability of the scale", "Malingering, from a below-chance pattern", "Mental deterioration, by comparing ‘hold’ and ‘don’t-hold’ subtests", "A specific learning disability, from a verbal–performance gap"], "correctAnswer": 2, "subject": "Intelligence & ability tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Wechsler noticed that some subtests ‘hold up’ with age and brain damage (Vocabulary, Information, Picture Completion, Object Assembly), while others ‘don’t hold’ (Digit Span, Digit Symbol, Block Design, Similarities). The gap gives a Deterioration Index or Quotient.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>A learning disability would not appear for the first time at 70.</li><li>Reliability needs two testings.</li><li>Malingering is shown by below-chance or implausible patterns, not this classic decline profile.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>RINPAS 2024 asked which are the hold subtests of the Wechsler scale.</li><li>Vocabulary is the best single estimate of premorbid intelligence.</li><li>Crystallized abilities ‘hold’; speed-dependent fluid abilities decline.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — RINPAS 2024. We recommend you keep this area ready."}, {"id": 87, "question": "Match the MMPI-2 clinical scale number (List I) with its name (List II): Codes:<div class=\"mt-wrap\"><table class=\"match-table\"><thead><tr><th>List I</th><th>List II</th></tr></thead><tbody><tr><td>1. Scale 2</td><td>a. Psychasthenia</td></tr><tr><td>2. Scale 4</td><td>b. Social Introversion</td></tr><tr><td>3. Scale 7</td><td>c. Depression</td></tr><tr><td>4. Scale 0</td><td>d. Psychopathic Deviate</td></tr></tbody></table></div>", "options": ["1-d, 2-c, 3-a, 4-b", "1-c, 2-d, 3-a, 4-b", "1-c, 2-a, 3-d, 4-b", "1-c, 2-d, 3-b, 4-a"], "correctAnswer": 1, "subject": "Objective personality tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The ten MMPI clinical scales: 1 Hs (Hypochondriasis), 2 D (Depression), 3 Hy (Hysteria), 4 Pd (Psychopathic Deviate), 5 Mf, 6 Pa (Paranoia), 7 Pt (Psychasthenia), 8 Sc (Schizophrenia), 9 Ma (Hypomania), 0 Si (Social Introversion).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The other codes swap scales 2 and 4 or 7 and 0.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>JANAS asked what Scale 7 (Psychasthenia) measures — obsessive-compulsive tendencies and anxiety.</li><li>RINPAS 2024 and JEPAS 2020 asked which is NOT an MMPI clinical scale.</li><li>Clinicians describe profiles by their highest two scales (‘code types’), e.g. a 4-9 profile.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>9 of them</b> (recent examples: IHBAS 2025, RINPAS 2024, IHBAS 2024, RML 2022). We recommend you focus on this area."}, {"id": 88, "question": "All of the following are factors measured by the Stanford–Binet Intelligence Scales, 5th edition, EXCEPT:", "options": ["Fluid Reasoning", "Working Memory", "Quantitative Reasoning", "Processing Speed"], "correctAnswer": 3, "subject": "Intelligence & ability tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The SB5 (Roid, 2003) measures five factors — Fluid Reasoning, Knowledge, Quantitative Reasoning, Visual–Spatial Processing and Working Memory — each in a verbal and a non-verbal form. Processing speed is not one of them.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Fluid Reasoning, Quantitative Reasoning and Working Memory are all SB5 factors.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The SB5 covers a very wide age range: 2 to 85+ years.</li><li>It uses ‘routing’ subtests to decide the starting level.</li><li>Processing Speed is a Wechsler index, which makes it the natural trap.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>11 of them</b> (recent examples: GBU 2025, NFSU 2023, GMCH 2023, JEMAS 2022). We recommend you focus on this area."}, {"id": 89, "question": "A major psychometric criticism of the Myers–Briggs Type Indicator (MBTI) is that it:", "options": ["Measures psychopathology rather than normal personality", "Forces continuous traits into either–or types, so many people change type on retesting", "Is based on Freud’s psychosexual theory", "Is a projective test with no scoring rules"], "correctAnswer": 1, "subject": "Objective personality tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The MBTI sorts people into 16 types based on four dichotomies (E/I, S/N, T/F, J/P). But the traits are really continuous, so people near the middle often get a different type when retested — a reliability problem.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>It is an objective self-report inventory.</li><li>It measures normal personality preferences.</li><li>It is based on Jung’s Psychological Types, not Freud.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Katharine Briggs and Isabel Briggs Myers developed it (published 1962).</li><li>IMHANS 2021 asked which tests trait theorists use (including the MBTI).</li><li>Type theories vs trait theories is a common concept question.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>3 papers</b> — IHBAS 2024, IMHANS 2021, JEPAS 2020. We recommend you keep this area ready."}, {"id": 90, "question": "A client is asked to record every cigarette she smokes in a small notebook. Her smoking drops during the first week simply because she is recording it. This effect is called:", "options": ["Halo effect", "Observer drift", "Regression to the mean", "Reactivity of self-monitoring"], "correctAnswer": 3, "subject": "Behavioural assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Reactivity means the act of observing a behaviour changes it. Self-monitoring usually reduces unwanted behaviour and increases desired behaviour, so it can be both an assessment tool and an intervention.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Observer drift – trained observers slowly change how they score over time.</li><li>Halo effect – one trait colours other ratings.</li><li>Regression to the mean – extreme scores move closer to the average on retesting.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>JANAS asked what self-monitoring involves (clients observing and recording their own behaviour).</li><li>The Hawthorne effect is reactivity in research settings (JEMAS 2024, Gurugram).</li><li>Reactivity is a threat to the validity of observational data.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>7 of them</b> (recent examples: RML 2024, JEMAS 2024, NFSU 2023, JEMAS 2022). We recommend you focus on this area."}, {"id": 91, "question": "To screen quickly whether a 2-year-old’s milestones are on track in an Indian clinic, and estimate a developmental age and developmental quotient, a psychologist can use:", "options": ["Developmental Screening Test (Bharat Raj)", "Bhatia Battery of Performance Tests", "Malin’s Intelligence Scale for Indian Children", "Bender Visual Motor Gestalt Test"], "correctAnswer": 0, "subject": "Indian tools & disability assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> J. Bharat Raj’s Developmental Screening Test (1977) is an Indian milestone-based screener for children from birth to about 15 years. It gives a developmental age and a developmental quotient (DQ).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>MISIC starts at about 6 years.</li><li>Bhatia Battery is for about 11–16 years.</li><li>The Bender test is for visuo-motor skills, not milestones.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>The Denver Developmental Screening Test (Frankenburg &amp; Dodds, 1967) is its Western counterpart.</li><li>DQ = (Developmental Age ÷ Chronological Age) × 100.</li><li>Screening tests only flag children for detailed assessment; they do not diagnose.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — RML 2022. We recommend you keep this area ready."}, {"id": 92, "question": "An MMPI-2 profile shows a very high F (Infrequency) scale and a low K (Correction) scale, with many clinical scales extremely elevated. The most likely interpretation is:", "options": ["Well-adjusted personality with good ego strength", "A valid profile of mild anxiety", "Over-reporting of symptoms (‘faking bad’) or random responding", "Defensive under-reporting (‘faking good’)"], "correctAnswer": 2, "subject": "Objective personality tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> F contains rare, unusual items; very high F means the person endorsed many of them. With low K (low defensiveness) and sky-high clinical scales, this points to exaggerating symptoms, a cry for help, or careless or random answering.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Faking good gives high L and K with low F.</li><li>Good ego strength shows moderate K and normal clinical scales.</li><li>Extremely elevated scales are not a picture of mild anxiety.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Validity scales: L (Lie), F (Infrequency), K (Correction), plus Fb, Fp, VRIN and TRIN.</li><li>Gough’s F–K index is a classic way to detect faking bad.</li><li>JANAS asked about citing only positive attributes on self-report (social desirability / faking good).</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>9 of them</b> (recent examples: IHBAS 2025, RINPAS 2024, IHBAS 2024, RML 2022). We recommend you focus on this area."}, {"id": 93, "question": "Two clinicians independently diagnose the same 50 patients as ‘depressed’ or ‘not depressed’. To measure their agreement after correcting for chance, one should use:", "options": ["Cohen’s kappa", "KR-20", "Cronbach’s alpha", "Pearson’s r"], "correctAnswer": 0, "subject": "Reliability, validity & norms", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Cohen’s kappa measures agreement between two raters on categories, after removing the agreement expected by chance alone.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Alpha and KR-20 measure internal consistency of items.</li><li>Pearson’s r is for continuous scores, not categories, and ignores chance agreement.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Inter-scorer reliability is especially important for projective and subjectively scored tests (IHBAS Paper-II).</li><li>Kappa above about 0.75 is usually taken as excellent agreement.</li><li>Fleiss’ kappa extends this to more than two raters; the ICC is used for continuous ratings.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>3 papers</b> — RINPAS 2024, IMHANS 2021, IHBAS Paper-II. We recommend you keep this area ready."}, {"id": 94, "question": "John Holland’s RIASEC model classifies people and work environments into six types. All of the following are Holland types, EXCEPT:", "options": ["Investigative", "Conventional", "Analytical", "Enterprising"], "correctAnswer": 2, "subject": "Vocational assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> RIASEC = Realistic, Investigative, Artistic, Social, Enterprising, Conventional. ‘Analytical’ is not one of the six.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Investigative, Enterprising and Conventional are all genuine Holland types.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>IMHANS 2025 asked what a mismatch between personality type and work environment leads to (lower satisfaction, career instability).</li><li>Holland’s Self-Directed Search (SDS) gives a three-letter code such as ‘SAE’.</li><li>Types next to each other on the hexagon are more similar than those opposite.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>1 paper</b> — IMHANS 2025. We recommend you keep this area ready."}, {"id": 95, "question": "Parents and teachers of an 8-year-old each fill in forms rating his inattention, restlessness and impulsivity in different settings. The instrument most likely used is the:", "options": ["Childhood Autism Rating Scale", "Bayley Scales of Infant Development", "Children’s Yale–Brown OCD Scale", "Conners Rating Scales"], "correctAnswer": 3, "subject": "Clinical assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The Conners Rating Scales (C. Keith Conners) collect parent, teacher and self-reports on ADHD symptoms and related problems. Ratings from more than one setting are needed, because ADHD symptoms must appear in two or more settings.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>CARS – autism.</li><li>CY-BOCS – childhood OCD.</li><li>Bayley – infant development.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>DSM-5: several ADHD symptoms must be present before age 12.</li><li>Vanderbilt and SNAP-IV are other ADHD rating scales.</li><li>Continuous Performance Tests measure sustained attention objectively.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>8 of them</b> (recent examples: IHBAS 2025, GBU 2025, JEMAS 2024, IHBAS 2024). We recommend you focus on this area."}, {"id": 96, "question": "The Present State Examination (PSE), later incorporated into the WHO’s SCAN, was developed by:", "options": ["Michael First and Robert Spitzer", "John Wing", "David Sheehan", "Jean Endicott"], "correctAnswer": 1, "subject": "Interviews, MSE & rating scales", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> John Wing and colleagues developed the PSE (9th edition, 1974) — a semi-structured interview for recording current symptoms. It became part of SCAN (Schedules for Clinical Assessment in Neuropsychiatry).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>First and Spitzer – SCID for DSM diagnoses.</li><li>Sheehan – MINI (Mini International Neuropsychiatric Interview).</li><li>Endicott – SADS (with Spitzer).</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>MP ENT asked who used the PSE with women four weeks after miscarriage.</li><li>The PSE was used in the WHO International Pilot Study of Schizophrenia.</li><li>Structured interviews improve diagnostic reliability.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — IHBAS 2025, MP ENT. We recommend you keep this area ready."}, {"id": 97, "question": "To assess the cognitive, language and motor development of an 18-month-old toddler born prematurely, the most suitable instrument is the:", "options": ["Stanford–Binet Intelligence Scales", "WISC-V", "Bayley Scales of Infant and Toddler Development", "Raven’s Coloured Progressive Matrices"], "correctAnswer": 2, "subject": "Developmental & child assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> The Bayley Scales (Nancy Bayley; now BSID-4) cover roughly 1 to 42 months. They assess cognitive, language, motor, social-emotional and adaptive development, and are widely used to follow up preterm babies.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The SB5 begins at 2 years.</li><li>WISC-V is for 6–16 years.</li><li>Raven’s CPM starts at about 5 years.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Infant test scores predict later IQ poorly, except at the low end.</li><li>The Gesell Developmental Schedules are older milestone-based norms (Gurugram and JEMAS 2024 asked about Gesell).</li><li>A developmental quotient (DQ) is used instead of IQ for infants.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — JEMAS 2024, Gurugram. We recommend you keep this area ready."}, {"id": 98, "question": "A man claiming compensation after a minor head injury scores well below chance (for example 15 out of 50) on a two-choice recognition memory test. This result most strongly suggests:", "options": ["Depression-related memory slowing", "Deliberately poor effort, as in malingering", "Early Alzheimer’s disease", "Severe genuine amnesia"], "correctAnswer": 1, "subject": "Neuropsychological assessment", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> On a two-choice test, even pure guessing gives about 50%. Scoring well BELOW chance means the person must know the right answers and is choosing the wrong ones. This points to deliberate poor effort. The Test of Memory Malingering (TOMM, Tombaugh, 1996) uses this logic.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Even severely amnesic patients score around chance, not far below it.</li><li>Dementia and depression lower scores but do not produce below-chance patterns.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>Malingering (external incentive) vs factitious disorder (sick role) — IHBAS 2025 asked the difference.</li><li>Other effort tests: Rey 15-Item Test, Word Memory Test; MMPI-2 validity scales (Fp, FBS) for symptom over-reporting.</li><li>The SIRS is a structured interview for feigned psychiatric symptoms.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>5 papers</b> — IHBAS 2025, JEMAS 2024, IHBAS 2024, RML 2022, JANAS. We recommend you keep this area ready."}, {"id": 99, "question": "Arrange the versions of the MMPI in the order in which they were published: I. MMPI-2-RF II. MMPI-3 III. MMPI (original) IV. MMPI-2", "options": ["III, I, IV, II", "IV, III, I, II", "III, IV, II, I", "III, IV, I, II"], "correctAnswer": 3, "subject": "Objective personality tests", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> MMPI (1943) → MMPI-2 (1989, 567 items) → MMPI-2-RF (2008, 338 items) → MMPI-3 (2020, 335 items).</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>The other orders place the RF after MMPI-3 or before MMPI-2.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>MMPI-A (1992) is the adolescent version.</li><li>The RF (‘Restructured Form’) introduced Restructured Clinical (RC) scales that reduce demoralization overlap.</li><li>Item counts (567, 338, 335) are favourite recall options.</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, this is a <b>high-frequency</b> area — related questions have appeared in <b>9 of them</b> (recent examples: IHBAS 2025, RINPAS 2024, IHBAS 2024, RML 2022). We recommend you focus on this area."}, {"id": 100, "question": "The multitrait–multimethod matrix (1959), used to show convergent and discriminant validity, was proposed by:", "options": ["Campbell and Fiske", "Kuder and Richardson", "Cronbach and Meehl", "Anastasi and Urbina"], "correctAnswer": 0, "subject": "Reliability, validity & norms", "subtopic": "", "difficulty": "", "explanation": "<p class=\"ex-why\"><b>Why:</b> Donald Campbell and Donald Fiske (1959) said a valid measure should correlate highly with other measures of the same trait (convergent) and weakly with measures of different traits (discriminant), across different methods.</p><div class=\"ex-sub\">Why not the others</div><ul class=\"ex-list\"><li>Cronbach and Meehl (1955) introduced the idea of construct validity.</li><li>Anastasi and Urbina wrote the textbook Psychological Testing.</li><li>Kuder and Richardson gave the KR-20 reliability formula.</li></ul><div class=\"ex-sub\">📌 Related topics you should know</div><ul class=\"ex-list\"><li>RINPAS 2024 asked what the multitrait–multimethod design is for.</li><li>Gurugram asked which is a type of construct validity (convergent/discriminant).</li><li>Factor analysis is another method for construct validation.</li><li>— End of Mock 5 —</li><li>Next: Mock 6 (5 October) — Psychopathology &amp; Disorders.  Queries: team@psychlogic.in</li></ul>", "examWatch": "As per PsychLogic's analysis of 22 previous-year papers, related questions have appeared in <b>2 papers</b> — RINPAS 2024, Gurugram. We recommend you keep this area ready."}];
